INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,81,'Aal-i-Imraan','وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيۡتُكُم مِّن كِتَٰبࣲ وَحِكۡمَةࣲ ثُمَّ جَآءَكُمۡ رَسُولࣱ مُّصَدِّقࣱ لِّمَا مَعَكُمۡ لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ قَالَ ءَأَقۡرَرۡتُمۡ وَأَخَذۡتُمۡ عَلَىٰ ذَٰلِكُمۡ إِصۡرِيۖ قَالُوٓاْ أَقۡرَرۡنَاۚ قَالَ فَٱشۡهَدُواْ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ','اور جب خدا نے پیغمبروں سے عہد لیا کہ جب میں تم کو کتاب اور دانائی عطا کروں پھر تمہارے پاس کوئی پیغمبر آئے جو تمہاری کتاب کی تصدیق کرے تو تمھیں ضرور اس پر ایمان لانا ہوگا اور ضرور اس کی مدد کرنی ہوگی اور (عہد لینے کے بعد) پوچھا کہ بھلا تم نے اقرار کیا اور اس اقرار پر میرا ذمہ لیا (یعنی مجھے ضامن ٹہرایا) انہوں نے کہا (ہاں) ہم نے اقرار کیا (خدا نے) فرمایا کہ تم (اس عہد وپیمان کے) گواہ رہو اور میں بھی تمہارے ساتھ گواہ ہوں','˹Remember˺ when Allah made a covenant with the prophets, ˹saying,˺ “Now that I have given you the Book and wisdom, if there comes to you a messenger confirming what you have, you must believe in him and support him.” He added, “Do you affirm this covenant and accept this commitment?” They said, “Yes, we do.” Allah said, “Then bear witness, and I too am a Witness.”','(और ऐ रसूल वह वक्त भी याद दिलाओ) जब ख़ुदा ने पैग़म्बरों से इक़रार लिया कि हम तुमको जो कुछ किताब और हिकमत (वगैरह) दे उसके बाद तुम्हारे पास कोई रसूल आए और जो किताब तुम्हारे पास उसकी तसदीक़ करे तो (देखो) तुम ज़रूर उस पर ईमान लाना, और ज़रूर उसकी मदद करना (और) ख़ुदा ने फ़रमाया क्या तुमने इक़रार लिया तुमने मेरे (एहद का) बोझ उठा लिया सबने अर्ज़ की हमने इक़रार किया इरशाद हुआ (अच्छा) तो आज के क़ौल व (क़रार के) आपस में एक दूसरे के गवाह रहना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,82,'Aal-i-Imraan','فَمَن تَوَلَّىٰ بَعۡدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ','تو جو اس کے بعد پھر جائیں وہ بد کردار ہیں','Whoever turns back after this, they will be the rebellious','और तुम्हारे साथ मैं भी एक गवाह हूं फिर उसके बाद जो शख्स (अपने क़ौल से) मुंह फेरे तो वही लोग बदचलन हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,83,'Aal-i-Imraan','أَفَغَيۡرَ دِينِ ٱللَّهِ يَبۡغُونَ وَلَهُۥٓ أَسۡلَمَ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعࣰ ا وَكَرۡهࣰ ا وَإِلَيۡهِ يُرۡجَعُونَ','کیا یہ (کافر) خدا کے دین کے سوا کسی اور دین کے طالب ہیں حالانکہ سب اہلِ آسمان و زمین خوشی یا زبردستی سے خدا کے فرماں بردار ہیں اور اسی کی طرف لوٹ کر جانے والے ہیں','Do they desire a way other than Allah’s—knowing that all those in the heavens and the earth submit to His Will, willingly or unwillingly, and to Him they will ˹all˺ be returned','तो क्या ये लोग ख़ुदा के दीन के सिवा (कोई और दीन) ढूंढते हैं हालॉकि जो (फ़रिश्ते) आसमानों में हैं और जो (लोग) ज़मीन में हैं सबने ख़ुशी ख़ुशी या ज़बरदस्ती उसके सामने अपनी गर्दन डाल दी है और (आख़िर सब) उसकी तरफ़ लौट कर जाएंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,84,'Aal-i-Imraan','قُلۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيۡنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدࣲ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ','کہو کہ ہم خدا پر ایمان لائے اور جو کتاب ہم پر نازل ہوئی اور جو صحیفے ابراہیم اور اسماعیل اور اسحٰق اور یعقوب اور ان کی اولاد پر اترے اور جو کتابیں موسیٰ اور عیسیٰ اور دوسرے انبیاء کو پروردگار کی طرف سے ملیں سب پر ایمان لائے ہم ان پیغمبروں میں سے کسی میں کچھ فرق نہیں کرتے اور ہم اسی (خدائے واحد) کے فرماں بردار ہیں','Say, ˹O Prophet,˺ “We believe in Allah and what has been revealed to us and what was revealed to Abraham, Ishmael, Isaac, Jacob, and his descendants; and what was given to Moses, Jesus, and other prophets from their Lord—we make no distinction between any of them, and to Him we ˹fully˺ submit.”','(ऐ रसूल उन लोगों से) कह दो कि हम तो ख़ुदा पर ईमान लाए और जो किताब हम पर नाज़िल हुई और जो (सहीफ़े) इबराहीम और इस्माईल और इसहाक़ और याकूब और औलादे याकूब पर नाज़िल हुये और मूसा और ईसा और दूसरे पैग़म्बरों को जो (जो किताब) उनके परवरदिगार की तरफ़ से इनायत हुई(सब पर ईमान लाए) हम तो उनमें से किसी एक में भी फ़र्क़ नहीं करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,85,'Aal-i-Imraan','وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينࣰ ا فَلَن يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ','اور جو شخص اسلام کے سوا کسی اور دین کا طالب ہوگا وہ اس سے ہرگز قبول نہیں کیا جائے گا اور ایسا شخص آخرت میں نقصان اٹھانے والوں میں ہوگا','Whoever seeks a way other than Islam, it will never be accepted from them, and in the Hereafter they will be among the losers','और हम तो उसी (यकता ख़ुदा) के फ़रमाबरदार हैं और जो शख्स इस्लाम के सिवा किसी और दीन की ख्वाहिश करे तो उसका वह दीन हरगिज़ कुबूल ही न किया जाएगा और वह आख़िरत में सख्त घाटे में रहेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,86,'Aal-i-Imraan','كَيۡفَ يَهۡدِي ٱللَّهُ قَوۡمࣰ ا كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ وَشَهِدُوٓاْ أَنَّ ٱلرَّسُولَ حَقࣱّ وَجَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','خدا ایسے لوگوں کو کیونکر ہدایت دے جو ایمان لانے کے بعد کافر ہوگئے اور (پہلے) اس بات کی گواہی دے چکے کہ یہ پیغمبر برحق ہے اور ان کے پاس دلائل بھی آگئے اور خدا بے انصافوں کو ہدایت نہیں دیتا','How will Allah guide a people who chose to disbelieve after they had believed, acknowledged the Messenger to be true, and received clear proofs? For Allah does not guide the wrongdoing people','भला ख़ुदा ऐसे लोगों की क्योंकर हिदायत करेगा जो इमाने लाने के बाद फिर काफ़िर हो गए हालॉकि वह इक़रार कर चुके थे कि पैग़म्बर (आख़िरूज़ज़मा) बरहक़ हैं और उनके पास वाजेए व रौशन मौजिज़े भी आ चुके थे और ख़ुदा ऐसी हठधर्मी करने वाले लोगों की हिदायत नहीं करता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,87,'Aal-i-Imraan','أُوْلَٰٓئِكَ جَزَآؤُهُمۡ أَنَّ عَلَيۡهِمۡ لَعۡنَةَ ٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ','ان لوگوں کی سزا یہ ہے کہ ان پر خدا کی اور فرشتوں کی اور انسانوں کی سب کی لعنت ہو','Their reward is that they will be condemned by Allah, the angels, and all of humanity','ऐसे लोगों की सज़ा यह है कि उनपर ख़ुदा और फ़रिश्तों और (दुनिया जहॉन के) सब लोगों की फिटकार हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,88,'Aal-i-Imraan','خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ','ہمیشہ اس لعنت میں (گرفتار) رہیں گے ان سے نہ تو عذاب ہلکا کیا جائے گا اور نہ انہیں مہلت دے جائے گی','They will be in Hell forever. Their punishment will not be lightened, nor will they be delayed ˹from it˺','और वह हमेशा उसी फिटकार में रहेंगे न तो उनके अज़ाब ही में तख्फ़ीफ़ की जाएगी और न उनको मोहलत दी जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,89,'Aal-i-Imraan','إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمٌ','ہاں جنہوں نے اس کے بعد توبہ کی اور اپنی حالت درست کر لی تو خدا بخشنے والا مہربان ہے','As for those who repent afterwards and mend their ways, then surely Allah is All-Forgiving, Most Merciful','मगर (हॉ) जिन लोगों ने इसके बाद तौबा कर ली और अपनी (ख़राबी की) इस्लाह कर ली तो अलबत्ता ख़ुदा बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,90,'Aal-i-Imraan','إِنَّ ٱلَّذِينَ كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ ثُمَّ ٱزۡدَادُواْ كُفۡرࣰ ا لَّن تُقۡبَلَ تَوۡبَتُهُمۡ وَأُوْلَٰٓئِكَ هُمُ ٱلضَّآلُّونَ','جو لوگ ایمان لانے کے بعد کافر ہو گئے پھر کفر میں بڑھتے گئے ایسوں کی توبہ ہرگز قبول نہ ہوگی اور یہ لوگ گمراہ ہیں','Indeed, those who disbelieve after having believed then increase in disbelief, their repentance will never be accepted. It is they who are astray','जो अपने ईमान के बाद काफ़िर हो बैठे फ़िर (रोज़ बरोज़ अपना) कुफ़्र बढ़ाते चले गये तो उनकी तौबा हरगिज़ न कुबूल की जाएगी और यही लोग (पल्ले दरजे के) गुमराह हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,91,'Aal-i-Imraan','إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارࣱ فَلَن يُقۡبَلَ مِنۡ أَحَدِهِم مِّلۡءُ ٱلۡأَرۡضِ ذَهَبࣰ ا وَلَوِ ٱفۡتَدَىٰ بِهِۦٓۗ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمࣱ وَمَا لَهُم مِّن نَّٰصِرِينَ','جو لوگ کافر ہوئے اور کفر ہی کی حالت میں مر گئے وہ اگر (نجات حاصل کرنی چاہیں اور) بدلے میں زمین بھر کر سونا دیں تو ہرگز قبول نہ کیا جائے گا ان لوگوں کو دکھ دینے والا عذاب ہو گا اور ان کی کوئی مدد نہیں کرے گا','Indeed, if each of those who disbelieve then die as disbelievers were to offer a ransom of enough gold to fill the whole world, it would never be accepted from them. It is they who will suffer a painful punishment, and they will have no helpers','बेशक जिन लोगों ने कुफ़्र इख्तियार किया और कुफ़्र की हालत में मर गये तो अगरचे इतना सोना भी किसी की गुलू ख़लासी (छुटकारा पाने) में दिया जाए कि ज़मीन भर जाए तो भी हरगिज़ न कुबूल किया जाएगा यही लोग हैं जिनके लिए दर्दनाक अज़ाब होगा और उनका कोई मददगार भी न होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,92,'Aal-i-Imraan','لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ وَمَا تُنفِقُواْ مِن شَيۡءࣲ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمࣱ‏','(مومنو!) جب تک تم ان چیزوں میں سے جو تمھیں عزیز ہیں (راہِ خدا میں) صرف نہ کرو گے کبھی نیکی حاصل نہ کر سکو گے اور جو چیز تم صرف کرو گے خدا اس کو جانتا ہے','You will never achieve righteousness until you donate some of what you cherish. And whatever you give is certainly well known to Allah','(लोगों) जब तक तुम अपनी पसन्दीदा चीज़ों में से कुछ राहे ख़ुदा में ख़र्च न करोगे हरगिज़ नेकी के दरजे पर फ़ायज़ नहीं हो सकते और तुम कोई');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,93,'Aal-i-Imraan','۞كُلُّ ٱلطَّعَامِ كَانَ حِلࣰّ ا لِّبَنِيٓ إِسۡرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسۡرَٰٓءِيلُ عَلَىٰ نَفۡسِهِۦ مِن قَبۡلِ أَن تُنَزَّلَ ٱلتَّوۡرَىٰةُۚ قُلۡ فَأۡتُواْ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَآ إِن كُنتُمۡ صَٰدِقِينَ','بنی اسرائیل کے لیے (تورات کے نازل ہونے سے) پہلے کھانے کی تمام چیزیں حلال تھیں بجز ان کے جو یعقوب نے خود اپنے اوپر حرام کر لی تھیں کہہ دو کہ اگر سچے ہو تو تورات لاؤ اور اسے پڑھو (یعنی دلیل پیش کرو)','All food was lawful for the children of Israel, except what Israel made unlawful for himself before the Torah was revealed. Say, ˹O Prophet,˺ “Bring the Torah and read it, if your claims are true.”','सी चीज़ भी ख़र्च करो ख़ुदा तो उसको ज़रूर जानता है तौरैत के नाज़िल होने के क़ब्ल याकूब ने जो जो चीज़े अपने ऊपर हराम कर ली थीं उनके सिवा बनी इसराइल के लिए सब खाने हलाल थे (ऐ रसूल उन यहूद से) कह दो कि अगर तुम (अपने दावे में सच्चे हो तो तौरेत ले आओ)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,94,'Aal-i-Imraan','فَمَنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ مِنۢ بَعۡدِ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ','جو اس کے بعد بھی خدا پر جھوٹے افترا کریں تو ایسے لوگ ہی بےانصاف ہیں','Then whoever still fabricates lies about Allah, they will be the ˹true˺ wrongdoers','और उसको (हमारे सामने) पढ़ो फिर उसके बाद भी जो कोई ख़ुदा पर झूठ तूफ़ान जोड़े तो (समझ लो) कि यही लोग ज़ालिम (हठधर्म) हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,95,'Aal-i-Imraan','قُلۡ صَدَقَ ٱللَّهُۗ فَٱتَّبِعُواْ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفࣰ اۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ','کہہ دو کہ خدا نے سچ فرمایا دیا پس دین ابراہیم کی پیروی کرو جو سب سے بےتعلق ہو کر ایک (خدا) کے ہو رہے تھے اور مشرکوں سے نہ تھے','Say, ˹O Prophet,˺ “Allah has declared the truth. So follow the Way of Abraham, the upright—who was not a polytheist.”','(ऐ रसूल) कह दो कि ख़ुदा ने सच फ़रमाया तो अब तुम मिल्लते इबराहीम (इस्लाम) की पैरवी करो जो बातिल से कतरा के चलते थे और मुशरेकीन से न थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,96,'Aal-i-Imraan','إِنَّ أَوَّلَ بَيۡتࣲ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكࣰ ا وَهُدࣰ ى لِّلۡعَٰلَمِينَ','پہلا گھر جو لوگوں (کے عبادت کرنے) کے لیے مقرر کیا گیا تھا وہی ہے جو مکے میں ہے بابرکت اور جہاں کے لیے موجبِ ہدایت','Surely the first House ˹of worship˺ established for humanity is the one at Bakkah—a blessed sanctuary and a guide for ˹all˺ people','लोगों (की इबादत) के वास्ते जो घर सबसे पहले बनाया गया वह तो यक़ीनन यही (काबा) है जो मक्के में है बड़ी (खैर व बरकत) वाला और सारे जहॉन के लोगों का रहनुमा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,97,'Aal-i-Imraan','فِيهِ ءَايَٰتُۢ بَيِّنَٰتࣱ مَّقَامُ إِبۡرَٰهِيمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنࣰ اۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَيۡتِ مَنِ ٱسۡتَطَاعَ إِلَيۡهِ سَبِيلࣰ اۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ','اس میں کھلی ہوئی نشانیاں ہیں جن میں سے ایک ابراہیم کے کھڑے ہونے کی جگہ ہے جو شخص اس (مبارک) گھر میں داخل ہوا اس نے امن پا لیا اور لوگوں پر خدا کا حق (یعنی فرض) ہے کہ جو اس گھر تک جانے کا مقدور رکھے وہ اس کا حج کرے اور جو اس حکم کی تعمیل نہ کرے گا تو خدا بھی اہلِ عالم سے بے نیاز ہے','In it are clear signs and the standing-place of Abraham. Whoever enters it should be safe. Pilgrimage to this House is an obligation by Allah upon whoever is able among the people. And whoever disbelieves, then surely Allah is not in need of ˹any of His˺ creation','इसमें (हुरमत की) बहुत सी वाज़े और रौशन निशानियॉ हैं (उनमें से) मुक़ाम इबराहीम है (जहॉ आपके क़दमों का पत्थर पर निशान है) और जो इस घर में दाख़िल हुआ अमन में आ गया और लोगों पर वाजिब है कि महज़ ख़ुदा के लिए ख़ानाए काबा का हज करें जिन्हे वहां तक पहुँचने की इस्तेताअत है और जिसने बावजूद कुदरत हज से इन्कार किया तो (याद रखे) कि ख़ुदा सारे जहॉन से बेपरवा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,98,'Aal-i-Imraan','قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعۡمَلُونَ','کہو کہ اہلِ کتاب! تم خدا کی آیتوں سے کیوں کفر کرتے ہو اور خدا تمہارے سب اعمال سے باخبر ہے','Say, ˹O Prophet,˺ “O People of the Book! Why do you deny the revelations of Allah, when Allah is a Witness to what you do?”','(ऐ रसूल) तुम कह दो कि ऐ अहले किताब खुदा की आयतो से क्यो मुन्किर हुए जाते हो हालॉकि जो काम काज तुम करते हो खुदा को उसकी (पूरी) पूरी इत्तिला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,99,'Aal-i-Imraan','قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ تَبۡغُونَهَا عِوَجࣰ ا وَأَنتُمۡ شُهَدَآءُۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ','کہو کہ اہلِ کتاب تم مومنوں کو خدا کے رستے سے کیوں روکتے ہو اور باوجود یہ کہ تم اس سے واقف ہو اس میں کجی نکالتے ہو اور خدا تمھارے کاموں سے بےخبر نہیں','Say, “O People of the Book! Why do you turn the believers away from the Way of Allah—striving to make it ˹appear˺ crooked, while you are witnesses ˹to its truth˺? And Allah is never unaware of what you do.”','(ऐ रसूल) तुम कह दो कि ऐ अहले किताब दीदए दानिस्ता खुदा की (सीधी) राह में (नाहक़ की) कज़ी ढूंढो (ढूंढ) के ईमान लाने वालों को उससे क्यों रोकते हो ओर जो कुछ तुम करते हो खुदा उससे बेख़बर नहीं है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,100,'Aal-i-Imraan','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ فَرِيقࣰ ا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ يَرُدُّوكُم بَعۡدَ إِيمَٰنِكُمۡ كَٰفِرِينَ','مومنو! اگر تم اہلِ کتاب کے کسی فریق کا کہا مان لو گے تو وہ تمھیں ایمان لانے کے بعد کافر بنا دیں گے','O believers! If you were to yield to a group of those who were given the Scripture, they would turn you back from belief to disbelief','ऐ ईमान वालों अगर तुमने अहले किताब के किसी फ़िरके क़ा भी कहना माना तो (याद रखो कि) वह तुमको ईमान लाने के बाद (भी) फिर दुबारा काफ़िर बना छोडेंग़े');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,101,'Aal-i-Imraan','وَكَيۡفَ تَكۡفُرُونَ وَأَنتُمۡ تُتۡلَىٰ عَلَيۡكُمۡ ءَايَٰتُ ٱللَّهِ وَفِيكُمۡ رَسُولُهُۥۗ وَمَن يَعۡتَصِم بِٱللَّهِ فَقَدۡ هُدِيَ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ‏','اور تم کیونکر کفر کرو گے جبکہ تم کو خدا کی آیتیں پڑھ پڑھ کر سنائی جاتی ہیں اور تم میں اس کے پیغمبر موجود ہیں اور جس نے خدا (کی ہدایت کی رسی) کو مضبوط پکڑ لیا وہ سیدھے رستے لگ گیا','How can you disbelieve when Allah’s revelations are recited to you and His Messenger is in your midst? Whoever holds firmly to Allah is surely guided to the Straight Path','और (भला) तुम क्योंकर काफ़िर बन जाओगे हालॉकि तुम्हारे सामने ख़ुदा की आयतें (बराबर) पढ़ी जाती हैं और उसके रसूल (मोहम्मद) भी तुममें (मौजूद) हैं और जो शख्स ख़ुदा से वाबस्ता हो वह (तो) जरूर सीधी राह पर लगा दिया गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,102,'Aal-i-Imraan','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ','مومنو! خدا سے ڈرو جیسا کہ اس سے ڈرنے کا حق ہے اور مرنا تو مسلمان ہی مرنا','O believers! Be mindful of Allah in the way He deserves, and do not die except in ˹a state of full˺ submission ˹to Him˺','ऐ ईमान वालों ख़ुदा से डरो जितना उससे डरने का हक़ है और तुम (दीन) इस्लाम के सिवा किसी और दीन पर हरगिज़ न मरना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,103,'Aal-i-Imraan','وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعࣰ ا وَلَا تَفَرَّقُواْۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَآءࣰ فَأَلَّفَ بَيۡنَ قُلُوبِكُمۡ فَأَصۡبَحۡتُم بِنِعۡمَتِهِۦٓ إِخۡوَٰنࣰ ا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةࣲ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنۡهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ','اور سب مل کر خدا کی (ہدایت کی رسی) کو مضبوط پکڑے رہنا اور متفرق نہ ہونا اور خدا کی اس مہربانی کو یاد کرو جب تم ایک دوسرے کے دشمن تھے تو اس نے تمہارے دلوں میں الفت ڈال دی اور تم اس کی مہربانی سے بھائی بھائی ہوگئے اور تم آگ کے گڑھے کے کنارے تک پہنچ چکے تھے تو خدا نے تم کو اس سے بچا لیا اس طرح خدا تم کو اپنی آیتیں کھول کھول کر سناتا ہے تاکہ تم ہدایت پاؤ','And hold firmly to the rope of Allah and do not be divided. Remember Allah’s favour upon you when you were enemies, then He united your hearts, so you—by His grace—became brothers. And you were at the brink of a fiery pit and He saved you from it. This is how Allah makes His revelations clear to you, so that you may be ˹rightly˺ guided','और तुम सब के सब (मिलकर) ख़ुदा की रस्सी मज़बूती से थामे रहो और आपस में (एक दूसरे) के फूट न डालो और अपने हाल (ज़ार) पर ख़ुदा के एहसान को तो याद करो जब तुम आपस में (एक दूसरे के) दुश्मन थे तो ख़ुदा ने तुम्हारे दिलों में (एक दूसरे की) उलफ़त पैदा कर दी तो तुम उसके फ़ज़ल से आपस में भाई भाई हो गए और तुम गोया सुलगती हुईआग की भट्टी (दोज़ख) के लब पर (खडे) थे गिरना ही चाहते थे कि ख़ुदा ने तुमको उससे बचा लिया तो ख़ुदा अपने एहकाम यूं वाजेए करके बयान करता है ताकि तुम राहे रास्त पर आ जाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,104,'Aal-i-Imraan','وَلۡتَكُن مِّنكُمۡ أُمَّةࣱ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','اور تم میں ایک جماعت ایسی ہونی چاہیئے جو لوگوں کو نیکی کی طرف بلائے اور اچھے کام کرنے کا حکم دے اور برے کاموں سے منع کرے یہی لوگ ہیں جو نجات پانے والے ہیں','Let there be a group among you who call ˹others˺ to goodness, encourage what is good, and forbid what is evil—it is they who will be successful','और तुमसे एक गिरोह ऐसे (लोगों का भी) तो होना चाहिये जो (लोगों को) नेकी की तरफ़ बुलाए अच्छे काम का हुक्म दे और बुरे कामों से रोके और ऐसे ही लोग (आख़ेरत में) अपनी दिली मुरादें पायेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,105,'Aal-i-Imraan','وَلَا تَكُونُواْ كَٱلَّذِينَ تَفَرَّقُواْ وَٱخۡتَلَفُواْ مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ عَظِيمࣱ‏','اور ان لوگوں کی طرح نہ ہونا جو متفرق ہو گئے اور احکام بین آنے کے بعد ایک دوسرےسے (خلاف و) اختلاف کرنے لگے یہ وہ لوگ ہیں جن کو قیامت کے دن بڑا عذاب ہوگا','And do not be like those who split ˹into sects˺ and differed after clear proofs had come to them. It is they who will suffer a tremendous punishment','और तुम (कहीं) उन लोगों के ऐसे न हो जाना जो आपस में फूट डाल कर बैठ रहे और रौशन (दलील) आने के बाद भी एक मुंह एक ज़बान न रहे और ऐसे ही लोगों के वास्ते बड़ा (भारी) अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,106,'Aal-i-Imraan','يَوۡمَ تَبۡيَضُّ وُجُوهࣱ وَتَسۡوَدُّ وُجُوهࣱۚ فَأَمَّا ٱلَّذِينَ ٱسۡوَدَّتۡ وُجُوهُهُمۡ أَكَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ','جس دن بہت سے منہ سفید ہوں گے اور بہت سے منہ سیاہ تو جن لوگوں کے منہ سیاہ ہوں گے (ان سے خدا فرمائے گا) کیا تم ایمان لا کر کافر ہوگئے تھے؟ سو (اب) اس کفر کے بدلے عذاب (کے مزے) چکھو','On that Day some faces will be bright while others gloomy. To the gloomy-faced it will be said, “Did you disbelieve after having believed? So taste the punishment for your disbelief.”','(उस दिन से डरो) जिस दिन कुछ लोगों के चेहरे तो सफैद नूरानी होंगे और कुछ (लोगो) के चेहरे सियाह जिन लोगों के मुहॅ में कालिक होगी (उनसे कहा जायेगा) हाए क्यों तुम तो ईमान लाने के बाद काफ़िर हो गए थे अच्छा तो (लो) (अब) अपने कुफ़्र की सज़ा में अज़ाब (के मजे) चखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,107,'Aal-i-Imraan','وَأَمَّا ٱلَّذِينَ ٱبۡيَضَّتۡ وُجُوهُهُمۡ فَفِي رَحۡمَةِ ٱللَّهِۖ هُمۡ فِيهَا خَٰلِدُونَ','اور جن لوگوں کے منہ سفید ہوں گے وہ خدا کی رحمت (کے باغوں) میں ہوں گے اور ان میں ہمیشہ رہیں گے','As for the bright-faced, they will be in Allah’s mercy, where they will remain forever','और जिनके चेहरे पर नूर बरसता होगा वह तो ख़ुदा की रहमत(बहिश्त) में होंगे (और) उसी में सदा रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,108,'Aal-i-Imraan','تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۗ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمࣰ ا لِّلۡعَٰلَمِينَ','یہ خدا کی آیتیں ہیں جو ہم تم کو صحت کے ساتھ پڑھ کر سناتے ہیں اور خدا اہلِ عالم پر ظلم نہیں کرنا چاہتا','These are Allah’s revelations We recite to you ˹O Prophet˺ in truth. And Allah desires no injustice to ˹His˺ creation','(ऐ रसूल) ये ख़ुदा की आयतें हैं जो हम तुमको ठीक (ठीक) पढ़ के सुनाते हैं और ख़ुदा सारे जहॉन के लोगों (से किसी) पर जुल्म करना नहीं चाहता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,109,'Aal-i-Imraan','وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ','اور جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب خدا ہی کا ہے اور سب کاموں کا رجوع (اور انجام) خدا ہی کی طرف ہے','To Allah ˹alone˺ belongs whatever is in the heavens and whatever is on the earth. And to Allah ˹all˺ matters will be returned ˹for judgment˺','और जो कुछ आसमानों में है और जो कुछ ज़मीन में है (सब) ख़ुदा ही का है और (आख़िर) सब कामों की रूज़ु ख़ुदा ही की तरफ़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,110,'Aal-i-Imraan','كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ أَهۡلُ ٱلۡكِتَٰبِ لَكَانَ خَيۡرࣰ ا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ ٱلۡفَٰسِقُونَ','(مومنو) جتنی امتیں (یعنی قومیں) لوگوں میں پیدا ہوئیں تم ان سب سے بہتر ہو کہ نیک کام کرنے کو کہتے ہو اور برے کاموں سے منع کرتے ہو اور خدا پر ایمان رکھتے ہو اور اگر اہلِ کتاب بھی ایمان لے آتے تو ان کے لیے بہت اچھا ہوتا ان میں ایمان لانے والے بھی ہیں (لیکن تھوڑے) اور اکثر نافرمان ہیں','You are the best community ever raised for humanity—you encourage good, forbid evil, and believe in Allah. Had the People of the Book believed, it would have been better for them. Some of them are faithful, but most are rebellious','तुम क्या अच्छे गिरोह हो कि (लोगों की) हिदायत के वास्ते पैदा किये गए हो तुम (लोगों को) अच्छे काम का हुक्म करते हो और बुरे कामों से रोकते हो और ख़ुदा पर ईमान रखते हो और अगर अहले किताब भी (इसी तरह) ईमान लाते तो उनके हक़ में बहुत अच्छा होता उनमें से कुछ ही तो ईमानदार हैं और अक्सर बदकार');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,111,'Aal-i-Imraan','لَن يَضُرُّوكُمۡ إِلَّآ أَذࣰ ىۖ وَإِن يُقَٰتِلُوكُمۡ يُوَلُّوكُمُ ٱلۡأَدۡبَارَ ثُمَّ لَا يُنصَرُونَ','اور یہ تمہیں خفیف سی تکلیف کے سوا کچھ نقصان نہیں پہنچا سکیں گے اور اگر تم سے لڑیں گے تو پیٹھ پھیر کر بھاگ جائیں گے پھر ان کو مدد بھی (کہیں سے) نہیں ملے گی','They can never inflict harm on you, except a little annoyance. But if they meet you in battle, they will flee and they will have no helpers','(मुसलमानों) ये लोग मामूली अज़ीयत के सिवा तुम्हें हरगिज़ ज़रर नहीं पहुंचा सकते और अगर तुमसे लड़ेंगे तो उन्हें तुम्हारी तरफ़ पीठ ही करनी होगी और फिर उनकी कहीं से मदद भी नहीं पहुंचेगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,112,'Aal-i-Imraan','ضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ أَيۡنَ مَا ثُقِفُوٓاْ إِلَّا بِحَبۡلࣲ مِّنَ ٱللَّهِ وَحَبۡلࣲ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبࣲ مِّنَ ٱللَّهِ وَضُرِبَتۡ عَلَيۡهِمُ ٱلۡمَسۡكَنَةُۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقࣲّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ','یہ جہاں نظر آئیں گے ذلت (کو دیکھو گے کہ) ان سے چمٹ رہی ہے بجز اس کے کہ یہ خدا اور (مسلمان) لوگوں کی پناہ میں آ جائیں اور یہ لوگ خدا کے غضب میں گرفتار ہیں اور ناداری ان سے لپٹ رہی ہے یہ اس لیے کہ خدا کی آیتوں سے انکار کرتےتھے اور (اس کے) پیغمبروں کو ناحق قتل کر دیتے تھے یہ اس لیے کہ یہ نافرمانی کیے جاتے اور حد سے بڑھے جاتے تھے','They will be stricken with disgrace wherever they go, unless they are protected by a covenant with Allah or a treaty with the people. They have invited the displeasure of Allah and have been branded with misery for rejecting Allah’s revelations and murdering ˹His˺ prophets unjustly. This is ˹a fair reward˺ for their disobedience and violations','और जहॉ कहीं हत्ते चढ़े उनपर रूसवाई की मार पड़ी मगर ख़ुदा के एहद (या) और लोगों के एहद के ज़रिये से (उनको कहीं पनाह मिल गयी) और फिर हेरफेर के खुदा के गज़ब में पड़ गए और उनपर मोहताजी की मार (अलग) पड़ी ये (क्यों) इस सबब से कि वह ख़ुदा की आयतों से इन्कार करते थे और पैग़म्बरों को नाहक़ क़त्ल करते थे ये सज़ा उसकी है कि उन्होंने नाफ़रमानी की और हद से गुज़र गए थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,113,'Aal-i-Imraan','۞لَيۡسُواْ سَوَآءࣰۗ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةࣱ قَآئِمَةࣱ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ وَهُمۡ يَسۡجُدُونَ','یہ بھی سب ایک جیسے نہیں ہیں ان اہلِ کتاب میں کچھ لوگ (حکمِ خدا پر) قائم بھی ہیں جو رات کے وقت خدا کی آیتیں پڑھتے اور (اس کے آگے) سجدہ کرتے ہیں','Yet they are not all alike: there are some among the People of the Book who are upright, who recite Allah’s revelations throughout the night, prostrating ˹in prayer˺','और ये लोग भी सबके सब यकसॉ नहीं हैं (बल्कि) अहले किताब से कुछ लोग तो ऐसे हैं कि (ख़ुदा के दीन पर) इस तरह साबित क़दम हैं कि रातों को ख़ुदा की आयतें पढ़ा करते हैं और वह बराबर सजदे किया करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,114,'Aal-i-Imraan','يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ وَأُوْلَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ','(اور) خدا پر اور روز آخرت پر ایمان رکھتے اور اچھے کام کرنےکو کہتے اور بری باتوں سے منع کرتےاور نیکیوں پر لپکتے ہیں اور یہی لوگ نیکوکار ہیں','They believe in Allah and the Last Day, encourage good and forbid evil, and race with one another in doing good. They are ˹truly˺ among the righteous','खुदा और रोज़े आख़ेरत पर ईमान रखते हैं और अच्छे काम का तो हुक्म करते हैं और बुरे कामों से रोकते हैं और नेक कामों में दौड़ पड़ते हैं और यही लोग तो नेक बन्दों से हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,115,'Aal-i-Imraan','وَمَا يَفۡعَلُواْ مِنۡ خَيۡرࣲ فَلَن يُكۡفَرُوهُۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ','اور یہ جس طرح کی نیکی کریں گے اس کی ناقدری نہیں کی جائے گی اور خدا پرہیزگاروں کو خوب جانتا ہے','They will never be denied the reward for any good they have done. And Allah has ˹perfect˺ knowledge of those mindful ˹of Him˺','और वह जो कुछ नेकी करेंगे उसकी हरगिज़ नाक़द्री न की जाएगी और ख़ुदा परहेज़गारों से खूब वाक़िफ़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,116,'Aal-i-Imraan','إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـࣰٔ اۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','جو لوگ کافر ہیں ان کے مال اور اولاد خدا کے غضب کو ہرگز نہیں ٹال سکیں گے اور یہ لوگ اہلِ دوزخ ہیں کہ ہمیشہ اسی میں رہیں گے','Indeed, neither the wealth nor children of the disbelievers will be of any benefit to them against Allah. It is they who will be the residents of the Fire. They will be there forever','बेशक जिन लोगों ने कुफ़्र इख्तेयार किया ख़ुदा (के अज़ाब) से बचाने में हरगिज़ न उनके माल ही कुछ काम आएंगे न उनकी औलाद और यही लोग जहन्नुमी हैं और हमेशा उसी में रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,117,'Aal-i-Imraan','مَثَلُ مَا يُنفِقُونَ فِي هَٰذِهِ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَثَلِ رِيحࣲ فِيهَا صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡمࣲ ظَلَمُوٓاْ أَنفُسَهُمۡ فَأَهۡلَكَتۡهُۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنۡ أَنفُسَهُمۡ يَظۡلِمُونَ','یہ جو مال دنیا کی زندگی میں خرچ کرتے ہیں اس کی مثال ہوا کی سی ہے جس میں سخت سردی ہو اور وہ ایسے لوگوں کی کھیتی پر جو اپنے آپ پر ظلم کرتے تھے چلے اور اسے تباہ کر دے اور خدا نے ان پر کچھ ظلم نہیں کیا بلکہ یہ خود اپنے اوپر ظلم کر رہے ہیں','The good they do in this worldly life is like the harvest of an evil people struck by a bitter wind, destroying it ˹completely˺. Allah never wronged them, but they wronged themselves','दुनिया की चन्द रोज़ा ज़िन्दगी में ये लोग जो कुछ (ख़िलाफ़ शरा) ख़र्च करते हैं उसकी मिसाल अन्धड़ की मिसाल है जिसमें बहुत पाला हो और वह उन लोगों के खेत पर जा पड़े जिन्होंने (कुफ़्र की वजह से) अपनी जानों पर सितम ढाया हो और फिर पाला उसे मार के (नास कर दे) और ख़ुदा ने उनपर जुल्म कुछ नहीं किया बल्कि उन्होंने आप अपने ऊपर जुल्म किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,118,'Aal-i-Imraan','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ بِطَانَةࣰ مِّن دُونِكُمۡ لَا يَأۡلُونَكُمۡ خَبَالࣰ ا وَدُّواْ مَا عَنِتُّمۡ قَدۡ بَدَتِ ٱلۡبَغۡضَآءُ مِنۡ أَفۡوَٰهِهِمۡ وَمَا تُخۡفِي صُدُورُهُمۡ أَكۡبَرُۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِۖ إِن كُنتُمۡ تَعۡقِلُونَ','مومنو! کسی غیر (مذہب کے آدمی) کو اپنا رازداں نہ بنانا یہ لوگ تمہاری خرابی اور (فتنہ انگیزی کرنے) میں کسی طرح کی کوتاہی نہیں کرتے اور چاہتے ہیں کہ (جس طرح ہو) تمہیں تکلیف پہنچے ان کی زبانوں سے تو دشمنی ظاہر ہوہی چکی ہے اور جو (کینے) ان کے سینوں میں مخفی ہیں وہ کہیں زیادہ ہیں اگر تم عقل رکھتے ہو تو ہم نے تم کو اپنی آیتیں کھول کھول کر سنا دی ہیں','O believers! Do not associate closely with others who would not miss a chance to harm you. Their only desire is to see you suffer. Their prejudice has become evident from what they say—and what their hearts hide is far worse. We have made Our revelations clear to you, if only you understood','ऐ ईमानदारों अपने (मोमिनीन) के सिवा (गैरो को) अपना राज़दार न बनाओ (क्योंकि) ये गैर लोग तुम्हारी बरबादी में कुछ उठा नहीं रखेंगे (बल्कि जितना ज्यादा तकलीफ़) में पड़ोगे उतना ही ये लोग ख़ुश होंगे दुश्मनी तो उनके मुंह से टपकती है और जो (बुग़ज़ व हसद) उनके दिलों में भरा है वह कहीं उससे बढ़कर है हमने तुमसे (अपने) एहकाम साफ़ साफ़ बयान कर दिये अगर तुम समझ रखते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,119,'Aal-i-Imraan','هَٰٓأَنتُمۡ أُوْلَآءِ تُحِبُّونَهُمۡ وَلَا يُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِٱلۡكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمۡ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ عَضُّواْ عَلَيۡكُمُ ٱلۡأَنَامِلَ مِنَ ٱلۡغَيۡظِۚ قُلۡ مُوتُواْ بِغَيۡظِكُمۡۗ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','دیکھو تم ایسے (صاف دل) لوگ ہو کہ ان لوگوں سے دوستی رکھتے ہو حالانکہ وہ تم سے دوستی نہیں رکھتے اور تم سب کتابوں پر ایمان رکھتے ہو (اور وہ تمہاری کتاب کو نہیں مانتے) اور جب تم سے ملتے ہیں تو کہتے ہیں ہم ایمان لے آئے اور جب الگ ہوتے ہیں تو تم پر غصے کے سبب انگلیاں کاٹ کاٹ کھاتے ہیں (ان سے) کہہ دو کہ (بدبختو) غصے میں مر جاؤ خدا تمہارے دلوں کی باتوں سے خوب واقف ہے','Here you are! You love them but they do not love you, and you believe in all Scriptures. When they meet you they say, “We believe.” But when alone, they bite their fingertips in rage. Say, ˹O Prophet,˺ “˹May you˺ die of your rage!” Surely Allah knows best what is ˹hidden˺ in the heart','ऐ लोगों तुम ऐसे (सीधे) हो कि तुम उनसे उलफ़त रखतो हो और वह तुम्हें (ज़रा भी) नहीं चाहते और तुम तो पूरी किताब (ख़ुदा) पर ईमान रखते हो और वह ऐसे नहीं हैं (मगर) जब तुमसे मिलते हैं तो कहने लगते हैं कि हम भी ईमान लाए और जब अकेले में होते हैं तो तुम पर गुस्से के मारे उंगलियों काटते हैं (ऐ रसूल) तुम कह दो कि (काटना क्या) तुम अपने गुस्से में जल मरो जो बातें तुम्हारे दिलों में हैं बेशक ख़ुदा ज़रूर जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,120,'Aal-i-Imraan','إِن تَمۡسَسۡكُمۡ حَسَنَةࣱ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ سَيِّئَةࣱ يَفۡرَحُواْ بِهَاۖ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ لَا يَضُرُّكُمۡ كَيۡدُهُمۡ شَيۡـًٔاۗ إِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ مُحِيطࣱ‏','اگر تمہیں آسودگی حاصل ہو تو ان کو بری لگتی ہے اور اگر رنج پہنچے تو خوش ہوتے ہیں اور اگر تم تکلیفوں کی برداشت اور (ان سے) کنارہ کشی کرتے رہو گے تو ان کا فریب تمھیں کچھ بھی نقصان نہ پہنچا سکے گا یہ جو کچھ کرتے ہیں خدا اس پر احاطہ کیے ہوئے ہے','When you ˹believers˺ are touched with good, they grieve; but when you are afflicted with evil, they rejoice. ˹Yet,˺ if you are patient and mindful ˹of Allah˺, their schemes will not harm you in the least. Surely Allah is Fully Aware of what they do','(ऐ ईमानदारों) अगर तुमको भलाई छू भी गयी तो उनको बुरा मालूम होता है और जब तुमपर कोई भी मुसीबत पड़ती है तो वह ख़ुश हो जाते हैं और अगर तुम सब्र करो और परहेज़गारी इख्तेयार करो तो उनका फ़रेब तुम्हें कुछ भी ज़रर नहीं पहुंचाएगा (क्योंकि) ख़ुदा तो उनकी कारस्तानियों पर हावी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,121,'Aal-i-Imraan','وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ ٱلۡمُؤۡمِنِينَ مَقَٰعِدَ لِلۡقِتَالِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ','اور (اس وقت کو یاد کرو) جب تم صبح کو اپنے گھر روانہ ہو کر ایمان والوں کو لڑائی کے لیے مورچوں پر (موقع بہ موقع) متعین کرنے لگے اور خدا سب کچھ سنتا اور جانتا ہے','˹Remember, O Prophet,˺ when you left your home in the early morning to position the believers in the battlefield. And Allah is All-Hearing, All-Knowing','और (ऐ रसूल) एक वक्त वो भी था जब तुम अपने बाल बच्चों से तड़के ही निकल खड़े हुए और मोमिनीन को लड़ाई के मोर्चों पर बिठा रहे थे और खुदा सब कुछ जानता और सुनता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,122,'Aal-i-Imraan','إِذۡ هَمَّت طَّآئِفَتَانِ مِنكُمۡ أَن تَفۡشَلَا وَٱللَّهُ وَلِيُّهُمَاۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ','اس وقت تم میں سے دو جماعتوں نے جی چھوڑ دینا چاہا مگر خدا ان کا مددگار تھا اور مومنوں کو خدا ہی پر بھروسہ رکھنا چاہیئے','˹Remember˺ when two groups among you ˹believers˺ were about to cower, then Allah reassured them. So in Allah let the believers put their trust','ये उस वक्त क़ा वाक़या है जब तुममें से दो गिरोहों ने ठान लिया था कि पसपाई करें और फिर (सॅभल गए) क्योंकि ख़ुदा तो उनका सरपरस्त था और मोमिनीन को ख़ुदा ही पर भरोसा रखना चाहिये');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,123,'Aal-i-Imraan','وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرࣲ وَأَنتُمۡ أَذِلَّةࣱۖ فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ','اور خدا نے جنگِ بدر میں بھی تمہاری مدد کی تھی اور اس وقت بھی تم بے سرو وسامان تھے پس خدا سے ڈرو (اور ان احسانوں کو یاد کرو) تاکہ شکر کرو','Indeed, Allah made you victorious at Badr when you were ˹vastly˺ outnumbered. So be mindful of Allah, perhaps you will be grateful','यक़ीनन ख़ुदा ने जंगे बदर में तुम्हारी मदद की (बावजूद के) तुम (दुश्मन के मुक़ाबले में) बिल्कुल बे हक़ीक़त थे (फिर भी) ख़ुदा ने फतेह दी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,124,'Aal-i-Imraan','إِذۡ تَقُولُ لِلۡمُؤۡمِنِينَ أَلَن يَكۡفِيَكُمۡ أَن يُمِدَّكُمۡ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفࣲ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُنزَلِينَ','جب تم مومنوں سے یہ کہہ (کر ان کے دل بڑھا) رہے تھے کہ کیا یہ کافی نہیں کہ پروردگار تین ہزار فرشتے نازل کر کے تمہیں مدد دے','˹Remember, O Prophet,˺ when you said to the believers, “Is it not enough that your Lord will send down a reinforcement of three thousand angels for your aid?”','पस तुम ख़ुदा से डरते रहो ताकि (उनके) शुक्रगुज़ार बनो (ऐ रसूल) उस वक्त तुम मोमिनीन से कह रहे थे कि क्या तुम्हारे लिए काफ़ी नहीं है कि तुम्हारा परवरदिगार तीन हज़ार फ़रिश्ते आसमान से भेजकर तुम्हारी मदद करे हॉ (ज़रूर काफ़ी है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,125,'Aal-i-Imraan','بَلَىٰٓۚ إِن تَصۡبِرُواْ وَتَتَّقُواْ وَيَأۡتُوكُم مِّن فَوۡرِهِمۡ هَٰذَا يُمۡدِدۡكُمۡ رَبُّكُم بِخَمۡسَةِ ءَالَٰفࣲ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُسَوِّمِينَ','ہاں اگر تم دل کو مضبوط رکھو اور (خدا سے) ڈرتے رہو اور کافر تم پر جوش کے ساتھ دفعتہً حملہ کردیں تو پروردگار پانچ ہزار فرشتے جن پر نشان ہوں گے تمہاری مدد کو بھیجے گا','Most certainly, if you ˹believers˺ are firm and mindful ˹of Allah˺ and the enemy launches a sudden attack on you, Allah will reinforce you with five thousand angels designated ˹for battle˺','बल्कि अगर तुम साबित क़दम रहो और (रसूल की मुख़ालेफ़त से) बचो और कुफ्फ़ार अपने (जोश में) तुमपर चढ़ भी आये तो तुम्हारा परवरदिगार ऐसे पॉच हज़ार फ़रिश्तों से तुम्हारी मदद करेगा जो निशाने जंग लगाए हुए डटे होंगे और ख़ुदा ने ये मदद सिर्फ तुम्हारी ख़ुशी के लिए की है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,126,'Aal-i-Imraan','وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَئِنَّ قُلُوبُكُم بِهِۦۗ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ','اور اس مدد کو خدا نے تمھارے لیے (ذریعہٴ) بشارت بنایا یعنی اس لیے کہ تمہارے دلوں کو اس سے تسلی حاصل ہو ورنہ مدد تو خدا ہی کی ہے جو غالب (اور) حکمت والا ہے','Allah ordained this ˹reinforcement˺ only as good news for you and reassurance for your hearts. And victory comes only from Allah—the Almighty, All-Wise—','और ताकि इससे तुम्हारे दिल की ढारस हो और (ये तो ज़ाहिर है कि) मदद जब होती है तो ख़ुदा ही की तरफ़ से जो सब पर ग़ालिब (और) हिकमत वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,127,'Aal-i-Imraan','لِيَقۡطَعَ طَرَفࣰ ا مِّنَ ٱلَّذِينَ كَفَرُوٓاْ أَوۡ يَكۡبِتَهُمۡ فَيَنقَلِبُواْ خَآئِبِينَ','(یہ خدا نے) اس لیے (کیا) کہ کافروں کی ایک جماعت کو ہلاک یا انہیں ذلیل ومغلوب کر دے کہ (جیسے آئے تھے ویسے ہی) ناکام واپس جائیں','to destroy a group of the disbelievers and humble the rest, causing them to withdraw in disappointment','(और यह मदद की भी तो) इसलिए कि काफ़िरों के एक गिरोह को कम कर दे या ऐसा चौपट कर दे कि (अपना सा) मुंह लेकर नामुराद अपने घर वापस चले जायें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,128,'Aal-i-Imraan','لَيۡسَ لَكَ مِنَ ٱلۡأَمۡرِ شَيۡءٌ أَوۡ يَتُوبَ عَلَيۡهِمۡ أَوۡ يُعَذِّبَهُمۡ فَإِنَّهُمۡ ظَٰلِمُونَ','(اے پیغمبر) اس کام میں تمہارا کچھ اختیار نہیں (اب دو صورتیں ہیں) یا خدا انکے حال پر مہربانی کرے یا انہیں عذاب دے کہ یہ ظالم لوگ ہیں','You ˹O Prophet˺ have no say in the matter. It is up to Allah to turn to them in mercy or punish them, for indeed they are wrongdoers','(ऐ रसूल) तुम्हारा तो इसमें कुछ बस नहीं चाहे ख़ुदा उनकी तौबा कुबूल करे या उनको सज़ा दे क्योंकि वह ज़ालिम तो ज़रूर हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,129,'Aal-i-Imraan','وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَٱللَّهُ غَفُورࣱ رَّحِيمࣱ‏','اور جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے سب خدا ہی کا ہے وہ جسے چاہے بخش دے اور جسے چاہے عذاب کرے اور خدا بخشنے والا مہربان ہے','To Allah ˹alone˺ belongs whatever is in the heavens and whatever is on the earth. He forgives whoever He wills, and punishes whoever He wills. And Allah is All-Forgiving, Most Merciful','और जो कुछ आसमानों में है और जो कुछ ज़मीन में है सब ख़ुदा ही का है जिसको चाहे बख्शे और जिसको चाहे सज़ा करे और ख़ुदा बड़ा बख्शने वाला मेहरबार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,130,'Aal-i-Imraan','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُواْ ٱلرِّبَوٰٓاْ أَضۡعَٰفࣰ ا مُّضَٰعَفَةࣰۖ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ','اےایمان والو! دگنا چوگنا سود نہ کھاؤ اور خدا سے ڈرو تاکہ نجات حاصل کرو','O believers! Do not consume interest, multiplying it many times over. And be mindful of Allah, so you may prosper','ऐ ईमानदारों सूद दनादन खाते न चले जाओ और ख़ुदा से डरो कि तुम छुटकारा पाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,131,'Aal-i-Imraan','وَٱتَّقُواْ ٱلنَّارَ ٱلَّتِيٓ أُعِدَّتۡ لِلۡكَٰفِرِينَ','اور (دوزخ کی) آگ سے بچو جو کافروں کے لیے تیار کی گئی ہے','Guard yourselves against the Fire prepared for the disbelievers','और जहन्नुम की उस आग से डरो जो काफ़िरों के लिए तैयार की गयी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,132,'Aal-i-Imraan','وَأَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ','اور خدا اور اس کے رسول کی اطاعت کرو تاکہ تم پر رحمت کی جائے','Obey Allah and the Messenger, so you may be shown mercy','और ख़ुदा और रसूल की फ़रमाबरदारी करो ताकि तुम पर रहम किया जाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,133,'Aal-i-Imraan','۞وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةࣲ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ','اپنے پروردگار کی بخشش اور بہشت کی طرف لپکو جس کا عرض آسمان اور زمین کے برابر ہے اور جو (خدا سے) ڈرنے والوں کے لیے تیار کی گئی ہے','And hasten towards forgiveness from your Lord and a Paradise as vast as the heavens and the earth, prepared for those mindful ˹of Allah˺','और अपने परवरदिगार के (सबब) बख्शिश और जन्नत की तरफ़ दौड़ पड़ो जिसकी (वुसअत सारे) आसमान और ज़मीन के बराबर है और जो परहेज़गारों के लिये मुहय्या की गयी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,134,'Aal-i-Imraan','ٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ','جو آسودگی اور تنگی میں (اپنا مال خدا کی راہ میں) خرچ کرتےہیں اور غصے کو روکتے اور لوگوں کے قصور معاف کرتے ہیں اور خدا نیکو کاروں کو دوست رکھتا ہے','˹They are˺ those who donate in prosperity and adversity, control their anger, and pardon others. And Allah loves the good-doers','जो ख़ुशहाली और कठिन वक्त में भी (ख़ुदा की राह पर) ख़र्च करते हैं और गुस्से को रोकते हैं और लोगों (की ख़ता) से दरगुज़र करते हैं और नेकी करने वालों से अल्लाह उलफ़त रखता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,135,'Aal-i-Imraan','وَٱلَّذِينَ إِذَا فَعَلُواْ فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ لِذُنُوبِهِمۡ وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ يُصِرُّواْ عَلَىٰ مَا فَعَلُواْ وَهُمۡ يَعۡلَمُونَ','اور وہ کہ جب کوئی کھلا گناہ یا اپنے حق میں کوئی اور برائی کر بیٹھتے ہیں تو خدا کو یاد کرتے اور اپنے گناہوں کی بخشش مانگتے ہیں اور خدا کے سوا گناہ بخش بھی کون سکتا ہے؟ اور جان بوجھ کر اپنے افعال پر اڑے نہیں رہتے','˹They are˺ those who, upon committing an evil deed or wronging themselves, remember Allah and seek forgiveness and do not knowingly persist in sin—and who forgives sins except Allah','और लोग इत्तिफ़ाक़ से कोई बदकारी कर बैठते हैं या आप अपने ऊपर जुल्म करते हैं तो ख़ुदा को याद करते हैं और अपने गुनाहों की माफ़ी मॉगते हैं और ख़ुदा के सिवा गुनाहों का बख्शने वाला और कौन है और जो (क़ूसूर) वह (नागहानी) कर बैठे तो जानबूझ कर उसपर हट नहीं करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,136,'Aal-i-Imraan','أُوْلَٰٓئِكَ جَزَآؤُهُم مَّغۡفِرَةࣱ مِّن رَّبِّهِمۡ وَجَنَّٰتࣱ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ','ایسے ہی لوگوں کا صلہ پروردگار کی طرف سے بخشش اور باغ ہیں جن کے نیچے نہریں بہہ رہی ہیں (اور) وہ ان میں ہمیشہ بستے رہیں گے اور (اچھے) کام کرنے والوں کا بدلہ بہت اچھا ہے','Their reward is forgiveness from their Lord and Gardens under which rivers flow, staying there forever. How excellent is the reward for those who work ˹righteousness˺','ऐसे ही लोगों की जज़ा उनके परवरदिगार की तरफ़ से बख्शिश है और वह बाग़ात हैं जिनके नीचे नहरें जारी हैं कि वह उनमें हमेशा रहेंगे और (अच्छे) चलन वालों की (भी) ख़ूब खरी मज़दूरी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,137,'Aal-i-Imraan','قَدۡ خَلَتۡ مِن قَبۡلِكُمۡ سُنَنࣱ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ','تم لوگوں سے پہلے بھی بہت سے واقعات گزر چکے ہیں تو تم زمین کی سیر کرکے دیکھ لو کہ جھٹلانے والوں کا کیسا انجام ہوا','Similar situations came to pass before you, so travel throughout the land and see the fate of the deniers','तुमसे पहले बहुत से वाक़यात गुज़र चुके हैं पस ज़रा रूए ज़मीन पर चल फिर कर देखो तो कि (अपने अपने वक्त क़े पैग़म्बरों को) झुठलाने वालों का अन्जाम क्या हुआ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,138,'Aal-i-Imraan','هَٰذَا بَيَانࣱ لِّلنَّاسِ وَهُدࣰ ى وَمَوۡعِظَةࣱ لِّلۡمُتَّقِينَ','یہ (قرآن) لوگوں کے لیے بیان صریح اور اہلِ تقویٰ کے لیے ہدایت اور نصیحت ہے','This is an insight to humanity—a guide and a lesson to the God-fearing','ये (जो हमने कहा) आम लोगों के लिए तो सिर्फ़ बयान (वाक़या) है मगर और परहेज़गारों के लिए हिदायत व नसीहत है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,139,'Aal-i-Imraan','وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ','اور (دیکھو) بے دل نہ ہونا اور نہ کسی طرح کا غم کرنا اگر تم مومن (صادق) ہو تو تم ہی غالب رہو گے','Do not falter or grieve, for you will have the upper hand, if you are ˹true˺ believers','और मुसलमानों काहिली न करो और (इस) इत्तफ़ाक़ी शिकस्त (ओहद से) कुढ़ो नहीं (क्योंकि) अगर तुम सच्चे मोमिन हो तो तुम ही ग़ालिब और वर रहोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,140,'Aal-i-Imraan','إِن يَمۡسَسۡكُمۡ قَرۡحࣱ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحࣱ مِّثۡلُهُۥۚ وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ','اگر تمہیں زخم (شکست) لگا ہے تو ان لوگوں کو بھی ایسا زخم لگ چکا ہے اور یہ دن ہیں کہ ہم ان کو لوگوں میں بدلتے رہتے ہیں اور اس سے یہ بھی مقصود تھا کہ خدا ایمان والوں کو متمیز کر دے اور تم میں سے گواہ بنائے اور خدا بےانصافوں کو پسند نہیں کرتا','If you have suffered injuries ˹at Uḥud˺, they suffered similarly ˹at Badr˺. We alternate these days ˹of victory and defeat˺ among people so that Allah may reveal the ˹true˺ believers, choose martyrs from among you—and Allah does not like the wrongdoers—','अगर (जंगे ओहद में) तुमको ज़ख्म लगा है तो उसी तरह (बदर में) तुम्हारे फ़रीक़ (कुफ्फ़ार को) भी ज़ख्म लग चुका है (उस पर उनकी हिम्मत तो न टूटी) ये इत्तफ़ाक़ाते ज़माना हैं जो हम लोगों के दरमियान बारी बारी उलट फेर किया करते हैं और ये (इत्तफ़ाक़ी शिकस्त इसलिए थी) ताकि ख़ुदा सच्चे ईमानदारों को (ज़ाहिरी) मुसलमानों से अलग देख लें और तुममें से बाज़ को दरजाए शहादत पर फ़ायज़ करें और ख़ुदा (हुक्मे रसूल से) सरताबी करने वालों को दोस्त नहीं रखता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,141,'Aal-i-Imraan','وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَمۡحَقَ ٱلۡكَٰفِرِينَ','اور یہ بھی مقصود تھا کہ خدا ایمان والوں کو خالص (مومن) بنا دے اور کافروں کو نابود کر دے','and distinguish the ˹true˺ believers and destroy the disbelievers','और ये (भी मंजूर था) कि सच्चे ईमानदारों को (साबित क़दमी की वजह से) निरा खरा अलग कर ले और नाफ़रमानों (भागने वालों) का मटियामेट कर दे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,142,'Aal-i-Imraan','أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَيَعۡلَمَ ٱلصَّٰبِرِينَ','کیا تم یہ سمجھتے ہو کہ (بےآزمائش) بہشت میں جا داخل ہو گے حالانکہ ابھی خدا نے تم میں سے جہاد کرنے والوں کو تو اچھی طرح معلوم کیا ہی نہیں اور (یہ بھی مقصود ہے) کہ وہ ثابت قدم رہنے والوں کو معلوم کرے','Do you think you will enter Paradise without Allah proving which of you ˹truly˺ struggled ˹for His cause˺ and patiently endured','(मुसलमानों) क्या तुम ये समझते हो कि सब के सब बहिश्त में चले ही जाओगे और क्या ख़ुदा ने अभी तक तुममें से उन लोगों को भी नहीं पहचाना जिन्होंने जेहाद किया और न साबित क़दम रहने वालों को ही पहचाना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,143,'Aal-i-Imraan','وَلَقَدۡ كُنتُمۡ تَمَنَّوۡنَ ٱلۡمَوۡتَ مِن قَبۡلِ أَن تَلۡقَوۡهُ فَقَدۡ رَأَيۡتُمُوهُ وَأَنتُمۡ تَنظُرُونَ','اور تم موت (شہادت) کے آنے سے پہلے اس کی تمنا کیا کرتے تھے سو تم نے اس کو آنکھوں سے دیکھ لیا','You certainly wished ˹for the opportunity˺ for martyrdom before encountering it, now you have seen it with your own eyes','तुम तो मौत के आने से पहले (लड़ाई में) मरने की तमन्ना करते थे बस अब तुमने उसको अपनी ऑख से देख लिया और तुम अब भी देख रहे हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,144,'Aal-i-Imraan','وَمَا مُحَمَّدٌ إِلَّا رَسُولࣱ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِيْن مَّاتَ أَوۡ قُتِلَ ٱنقَلَبۡتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡۚ وَمَن يَنقَلِبۡ عَلَىٰ عَقِبَيۡهِ فَلَن يَضُرَّ ٱللَّهَ شَيۡـࣰٔ اۚ وَسَيَجۡزِي ٱللَّهُ ٱلشَّٰكِرِينَ','اور محمد (صلی الله علیہ وسلم) تو صرف (خدا کے) پیغمبر ہیں ان سے پہلے بھی بہت سے پیغمبر ہو گزرے ہیں بھلا اگر یہ مر جائیں یا مارے جائیں تو تم الٹے پاؤں پھر جاؤ؟ (یعنی مرتد ہو جاؤ؟) اور جو الٹے پاؤں پھر جائے گا تو خدا کا کچھ نقصان نہ کر سکے گا اور خدا شکر گزاروں کو (بڑا) ثواب دے گا','Muḥammad is no more than a messenger; other messengers have gone before him. If he were to die or to be killed, would you regress into disbelief? Those who do so will not harm Allah whatsoever. And Allah will reward those who are grateful','(फिर लड़ाई से जी क्यों चुराते हो) और मोहम्मद तो सिर्फ रसूल हैं (ख़ुदा नहीं) इनसे पहले बहुतेरे पैग़म्बर गुज़र चुके हैं फिर क्या अगर मोहम्मद अपनी मौत से मर जॉए या मार डाले जाएं तो तुम उलटे पॉव (अपने कुफ़्र की तरफ़) पलट जाओगे और जो उलटे पॉव फिरेगा (भी) तो (समझ लो) हरगिज़ ख़ुदा का कुछ भी नहीं बिगड़ेगा और अनक़रीब ख़ुदा का शुक्र करने वालों को अच्छा बदला देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,145,'Aal-i-Imraan','وَمَا كَانَ لِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَٰبࣰ ا مُّؤَجَّلࣰ اۗ وَمَن يُرِدۡ ثَوَابَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَن يُرِدۡ ثَوَابَ ٱلۡأٓخِرَةِ نُؤۡتِهِۦ مِنۡهَاۚ وَسَنَجۡزِي ٱلشَّٰكِرِينَ','اور کسی شخص میں طاقت نہیں کہ خدا کے حکم کے بغیر مر جائے (اس نے موت کا) وقت مقرر کر کے لکھ رکھا ہے اور جو شخص دنیا میں (اپنے اعمال کا) بدلہ چاہے اس کو ہم یہیں بدلہ دے دیں گے اور جو آخرت میں طالبِ ثواب ہو اس کو وہاں اجر عطا کریں گے اور ہم شکر گزاروں کو عنقریب (بہت اچھا) صلہ دیں گے','No soul can ever die without Allah’s Will at the destined time. Those who desire worldly gain, We will let them have it, and those who desire heavenly reward, We will grant it to them. And We will reward those who are grateful','और बगैर हुक्मे ख़ुदा के तो कोई शख्स मर ही नहीं सकता वक्ते मुअय्यन तक हर एक की मौत लिखी हुई है और जो शख्स (अपने किए का) बदला दुनिया में चाहे तो हम उसको इसमें से दे देते हैं और जो शख्स आख़ेरत का बदला चाहे उसे उसी में से देंगे और (नेअमत ईमान के) शुक्र करने वालों को बहुत जल्द हम जज़ाए खैर देंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,146,'Aal-i-Imraan','وَكَأَيِّن مِّن نَّبِيࣲّ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرࣱ فَمَا وَهَنُواْ لِمَآ أَصَابَهُمۡ فِي سَبِيلِ ٱللَّهِ وَمَا ضَعُفُواْ وَمَا ٱسۡتَكَانُواْۗ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ','اور بہت سے نبی ہوئے ہیں جن کے ساتھ ہو کر اکثر اہل الله (خدا کے دشمنوں سے) لڑے ہیں تو جو مصبتیں ان پر راہِ خدا میں واقع ہوئیں ان کے سبب انہوں نے نہ تو ہمت ہاری اور نہ بزدلی کی نہ (کافروں سے) دبے اور خدا استقلال رکھنے والوں کو دوست رکھتا ہے','˹Imagine˺ how many devotees fought along with their prophets and never faltered despite whatever ˹losses˺ they suffered in the cause of Allah, nor did they weaken or give in! Allah loves those who persevere','और (मुसलमानों तुम ही नहीं) ऐसे पैग़म्बर बहुत से गुज़र चुके हैं जिनके साथ बहुतेरे अल्लाह वालों ने (राहे खुदा में) जेहाद किया और फिर उनको ख़ुदा की राह में जो मुसीबत पड़ी है न तो उन्होंने हिम्मत हारी न बोदापन किया (और न दुशमन के सामने) गिड़गिड़ाने लगे और साबित क़दम रहने वालों से ख़ुदा उलफ़त रखता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,147,'Aal-i-Imraan','وَمَا كَانَ قَوۡلَهُمۡ إِلَّآ أَن قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ','اور (اس حالت میں) ان کے منہ سے کوئی بات نکلتی ہے تو یہی کہ اے پروردگار ہمارے گناہ اور زیادتیاں جو ہم اپنے کاموں میں کرتے رہے ہیں معاف فرما اور ہم کو ثابت قدم رکھ اور کافروں پر فتح عنایت فرما','And all they said was, “Our Lord! Forgive our sins and excesses, make our steps firm, and grant us victory over the disbelieving people.”','और लुत्फ़ ये है कि उनका क़ौल इसके सिवा कुछ न था कि दुआएं मॉगने लगें कि ऐ हमारे पालने वाले हमारे गुनाह और अपने कामों में हमारी ज्यादतियॉ माफ़ कर और दुश्मनों के मुक़ाबले में हमको साबित क़दम रख और काफ़िरों के गिरोह पर हमको फ़तेह दे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,148,'Aal-i-Imraan','فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنۡيَا وَحُسۡنَ ثَوَابِ ٱلۡأٓخِرَةِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ','تو خدا نے ان کو دنیا میں بھی بدلہ دیا اور آخرت میں بھی بہت اچھا بدلہ (دے گا) اور خدا نیکو کاروں کو دوست رکھتا ہے','So Allah gave them the reward of this world and the excellent reward of the Hereafter. For Allah loves the good-doers','तो ख़ुदा ने उनको दुनिया में बदला (दिया) और आख़िरत में अच्छा बदला ईनायत फ़रमाया और ख़ुदा नेकी करने वालों को दोस्त रखता (ही) है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,149,'Aal-i-Imraan','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ ٱلَّذِينَ كَفَرُواْ يَرُدُّوكُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ','مومنو! اگر تم کافروں کا کہا مان لو گے تو وہ تم کو الٹے پاؤں پھیر کر (مرتد کر) دیں گے پھر تم بڑے خسارے میں پڑ جاؤ گے','O believers! If you yield to the disbelievers, they will drag you back to disbelief—and you will become losers','ऐ ईमानदारों अगर तुम लोगों ने काफ़िरों की पैरवी कर ली तो (याद रखो) वह तुमको उलटे पॉव (कुफ़्र की तरफ़) फेर कर ले जाऐंगे फिर उलटे तुम ही घाटे में आ जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,150,'Aal-i-Imraan','بَلِ ٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ خَيۡرُ ٱلنَّٰصِرِينَ','(یہ تمہارے مددگار نہیں ہیں) بلکہ خدا تمہارا مددگار ہے اور وہ سب سے بہتر مددگار ہے','But no! Allah is your Guardian, and He is the best Helper','(तुम किसी की मदद के मोहताज नहीं) बल्कि ख़ुदा तुम्हारा सरपरस्त है और वह सब मददगारों से बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,151,'Aal-i-Imraan','سَنُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ بِمَآ أَشۡرَكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنࣰ اۖ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَبِئۡسَ مَثۡوَى ٱلظَّٰلِمِينَ','ہم عنقریب کافروں کے دلوں میں تمہارا رعب بٹھا دیں گے کیونکہ یہ خدا کے ساتھ شرک کرتے ہیں جس کی اس نے کوئی بھی دلیل نازل نہیں کی اور ان کا ٹھکانہ دوزخ ہے وہ ظالموں کا بہت بُرا ٹھکانا ہے','We will cast horror into the hearts of the disbelievers for associating ˹false gods˺ with Allah—a practice He has never authorized. The Fire will be their home—what an evil place for the wrongdoers to stay','(तुम घबराओ नहीं) हम अनक़रीब तुम्हारा रोब काफ़िरों के दिलों में जमा देंगे इसलिए कि उन लोगों ने ख़ुदा का शरीक बनाया (भी तो) इस चीज़ बुत को जिसे ख़ुदा ने किसी क़िस्म की हुकूमत नहीं दी और (आख़िरकार) उनका ठिकाना दौज़ख़ है और ज़ालिमों का (भी क्या) बुरा ठिकाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,152,'Aal-i-Imraan','وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥٓ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم مِّنۢ بَعۡدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَۚ مِنكُم مَّن يُرِيدُ ٱلدُّنۡيَا وَمِنكُم مَّن يُرِيدُ ٱلۡأٓخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِيَبۡتَلِيَكُمۡۖ وَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِينَ','اور خدا نے اپنا وعدہ سچا کر دیا (یعنی) اس وقت جبکہ تم کافروں کو اس کے حکم سے قتل کر رہے تھے یہاں تک کہ جو تم چاہتے تھے خدا نے تم کو دکھا دیا اس کے بعد تم نے ہمت ہار دی اور حکم (پیغمبر) میں جھگڑا کرنے لگے اور اس کی نافرمانی کی بعض تو تم میں سے دنیا کے خواستگار تھے اور بعض آخرت کے طالب اس وقت خدا نے تم کو ان (کے مقابلے) سے پھیر (کر بھگا) دیا تاکہ تمہاری آزمائش کرے اور اس نے تمہارا قصور معاف کر دیا اور خدا مومنو پر بڑا فضل کرنے والا ہے','Indeed, Allah fulfilled His promise to you when you ˹initially˺ swept them away by His Will, then your courage weakened and you disputed about the command and disobeyed, after Allah had brought victory within your reach. Some of you were after worldly gain while others desired a heavenly reward. He denied you victory over them as a test, yet He has pardoned you. And Allah is Gracious to the believers','बेशक खुदा ने (जंगे औहद में भी) अपना (फतेह का) वायदा सच्चा कर दिखाया था जब तुम उसके हुक्म से (पहले ही हमले में) उन (कुफ्फ़ार) को खूब क़त्ल कर रहे थे यहॉ तक की तुम्हारे पसन्द की चीज़ (फ़तेह) तुम्हें दिखा दी उसके बाद भी तुमने (माले ग़नीमत देखकर) बुज़दिलापन किया और हुक्में रसूल (मोर्चे पर जमे रहने) झगड़ा किया और रसूल की नाफ़रमानी की तुममें से कुछ तो तालिबे दुनिया हैं (कि माले ग़नीमत की तरफ़) से झुक पड़े और कुछ तालिबे आख़िरत (कि रसूल पर अपनी जान फ़िदा कर दी) फिर (बुज़दिलेपन ने) तुम्हें उन (कुफ्फ़ार) की की तरफ से फेर दिया (और तुम भाग खड़े हुए) उससे ख़ुदा को तुम्हारा (ईमान अख़लासी) आज़माना मंज़ूर था और (उसपर भी) ख़ुदा ने तुमसे दरगुज़र की और खुदा मोमिनीन पर बड़ा फ़ज़ल करने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,153,'Aal-i-Imraan','۞إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُۥنَ عَلَىٰٓ أَحَدࣲ وَٱلرَّسُولُ يَدۡعُوكُمۡ فِيٓ أُخۡرَىٰكُمۡ فَأَثَٰبَكُمۡ غَمَّۢا بِغَمࣲّ لِّكَيۡلَا تَحۡزَنُواْ عَلَىٰ مَا فَاتَكُمۡ وَلَا مَآ أَصَٰبَكُمۡۗ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ','(وہ وقت بھی یاد کرنے کے لائق ہے) جب تم لوگ دور بھاگے جاتے تھے اور کسی کو پیچھے پھر کر نہیں دیکھتے تھے اور رسول الله تم کو تمہارے پیچھے کھڑے بلا رہے تھے تو خدا نے تم کو غم پر غم پہنچایا تاکہ جو چیز تمہارے ہاتھ سے جاتی رہی یا جو مصیبت تم پر واقع ہوئی ہے اس سے تم اندوہ ناک نہ ہو اور خدا تمہارے سب اعمال سے خبردار ہے','˹Remember˺ when you were running far away ˹in panic˺—not looking at anyone—while the Messenger was calling to you from behind! So Allah rewarded your disobedience with distress upon distress. Now, do not grieve over the victory you were denied or the injury you suffered. And Allah is All-Aware of what you do','(मुसलमानों तुम) उस वक्त क़ो याद करके शर्माओ जब तुम (बदहवास) भागे पहाड़ पर चले जाते थे पस (चूंकि) रसूल को तुमने (आज़ारदा) किया ख़ुदा ने भी तुमको (इस) रंज की सज़ा में (शिकस्त का) रंज दिया ताकि जब कभी तुम्हारी कोई चीज़ हाथ से जाती रहे या कोई मुसीबत पड़े तो तुम रंज न करो और सब्र करना सीखो और जो कुछ तुम करते हो ख़ुदा उससे ख़बरदार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,154,'Aal-i-Imraan','ثُمَّ أَنزَلَ عَلَيۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةࣰ نُّعَاسࣰ ا يَغۡشَىٰ طَآئِفَةࣰ مِّنكُمۡۖ وَطَآئِفَةࣱ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ يَظُنُّونَ بِٱللَّهِ غَيۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَٰهِلِيَّةِۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءࣲۗ قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ يُخۡفُونَ فِيٓ أَنفُسِهِم مَّا لَا يُبۡدُونَ لَكَۖ يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءࣱ مَّا قُتِلۡنَا هَٰهُنَاۗ قُل لَّوۡ كُنتُمۡ فِي بُيُوتِكُمۡ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ وَلِيَبۡتَلِيَ ٱللَّهُ مَا فِي صُدُورِكُمۡ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمۡۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','پھر خدا نے غم ورنج کے بعد تم پر تسلی نازل فرمائی (یعنی) نیند کہ تم میں سے ایک جماعت پر طاری ہو گئی اور کچھ لوگ جن کو جان کے لالے پڑ رہے تھے خدا کے بارے میں ناحق (ایام) کفر کے سے گمان کرتے تھے اور کہتے تھے بھلا ہمارے اختیار کی کچھ بات ہے؟ تم کہہ دو کہ بےشک سب باتیں خدا ہی کے اختیار میں ہیں یہ لوگ (بہت سی باتیں) دلوں میں مخفی رکھتے ہیں جو تم پر ظاہر نہیں کرتے تھے کہتے تھے کہ ہمارے بس کی بات ہوتی تو ہم یہاں قتل ہی نہ کیے جاتے کہہ دو کہ اگر تم اپنے گھروں میں بھی ہوتے تو جن کی تقدیر میں مارا جانا لکھا تھا وہ اپنی اپنی قتل گاہوں کی طرف ضرور نکل آتے اس سے غرض یہ تھی کہ خدا تمہارے سینوں کی باتوں کو آزمائے اور جو کچھ تمہارے دلوں میں ہے اس کو خالص اور صاف کر دے اور خدا دلوں کی باتوں سے خوب واقف ہے','Then after distress, He sent down serenity in the form of drowsiness overcoming some of you, while others were disturbed by evil thoughts about Allah—the thoughts of ˹pre-Islamic˺ ignorance. They ask, “Do we have a say in the matter?” Say, ˹O Prophet,˺ “All matters are destined by Allah.” They conceal in their hearts what they do not reveal to you. They say ˹to themselves˺, “If we had any say in the matter, none of us would have come to die here.” Say, ˹O Prophet,˺ “Even if you were to remain in your homes, those among you who were destined to be killed would have met the same fate.” Through this, Allah tests what is within you and purifies what is in your hearts. And Allah knows best what is ˹hidden˺ in the heart','फिर ख़ुदा ने इस रंज के बाद तुमपर इत्मिनान की हालत तारी की कि तुममें से एक गिरोह का (जो सच्चे ईमानदार थे) ख़ूब गहरी नींद आ गयी और एक गिरोह जिनको उस वक्त भी (भागने की शर्म से) जान के लाले पड़े थे ख़ुदा के साथ (ख्वाह मख्वाह) ज़मानाए जिहालत की ऐसी बदगुमानियॉ करने लगे और कहने लगे भला क्या ये अम्र (फ़तेह) कुछ भी हमारे इख्तियार में है (ऐ रसूल) कह दो कि हर अम्र का इख्तियार ख़ुदा ही को है (ज़बान से तो कहते ही है नहीं) ये अपने दिलों में ऐसी बातें छिपाए हुए हैं जो तुमसे ज़ाहिर नहीं करते (अब सुनो) कहते हैं कि इस अम्र (फ़तेह) में हमारा कुछ इख़्तियार होता तो हम यहॉ मारे न जाते (ऐ रसूल उनसे) कह दो कि तुम अपने घरों में रहते तो जिन जिन की तकदीर में लड़के मर जाना लिखा था वह अपने (घरो से) निकल निकल के अपने मरने की जगह ज़रूर आ जाते और (ये इस वास्ते किया गया) ताकि जो कुछ तुम्हारे दिल में है उसका इम्तिहान कर दे और ख़ुदा तो दिलों के राज़ खूब जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,155,'Aal-i-Imraan','إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا كَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمࣱ‏','جو لوگ تم میں سے (اُحد کے دن) جبکہ (مومنوں اور کافروں کی) دو جماعتیں ایک دوسرے سے گتھ گئیں (جنگ سے) بھاگ گئے تو ان کے بعض افعال کے سبب شیطان نے ان کو پھسلا دیا مگر خدا نے ان کا قصور معاف کر دیا بےشک خدا بخشنے والا اور بردبار ہے','Indeed, those ˹believers˺ who fled on the day when the two armies met were made to slip by Satan because of their misdeeds. But Allah has pardoned them. Surely Allah is All-Forgiving, Most Forbearing','बेशक जिस दिन (जंगे औहद में) दो जमाअतें आपस में गुथ गयीं उस दिन जो लोग तुम (मुसलमानों) में से भाग खड़े हुए (उसकी वजह ये थी कि) उनके बाज़ गुनाहों (मुख़ालफ़ते रसूल) की वजह से शैतान ने बहका के उनके पॉव उखाड़ दिए और (उसी वक्त तो) ख़ुदा ने ज़रूर उनसे दरगुज़र की बेशक ख़ुदा बड़ा बख्शने वाला बुर्दवार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,156,'Aal-i-Imraan','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ كَفَرُواْ وَقَالُواْ لِإِخۡوَٰنِهِمۡ إِذَا ضَرَبُواْ فِي ٱلۡأَرۡضِ أَوۡ كَانُواْ غُزࣰّ ى لَّوۡ كَانُواْ عِندَنَا مَا مَاتُواْ وَمَا قُتِلُواْ لِيَجۡعَلَ ٱللَّهُ ذَٰلِكَ حَسۡرَةࣰ فِي قُلُوبِهِمۡۗ وَٱللَّهُ يُحۡيِۦ وَيُمِيتُۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرࣱ‏','مومنو! ان لوگوں جیسے نہ ہونا جو کفر کرتے ہیں اور ان کے (مسلمان) بھائی جب (خدا کی راہ میں) سفر کریں (اور مر جائیں) یا جہاد کو نکلیں (اور مارے جائیں) تو ان کی نسبت کہتے ہیں کہ اگر وہ ہمارے پاس رہتے تو نہ مرتے اور نہ مارے جاتے۔ ان باتوں سے مقصود یہ ہے کہ خدا ان لوگوں کے دلوں میں افسوس پیدا کر دے اور زندگی اور موت تو خدا ہی دیتا ہے اور خدا تمہارے سب کاموں کو دیکھ رہا ہے','O believers! Do not be like the unfaithful who say about their brothers who travel throughout the land or engage in battle, “If they had stayed with us, they would not have died or been killed.” Allah makes such thinking a cause of agony in their hearts. It is Allah who gives life and causes death. And Allah is All-Seeing of what you do','ऐ ईमानदारों उन लोगों के ऐसे न बनो जो काफ़िर हो गए भाई बन्द उनके परदेस में निकले हैं या जेहाद करने गए हैं (और वहॉ) मर (गए) तो उनके बारे में कहने लगे कि वह हमारे पास रहते तो न मरते ओर न मारे जाते (और ये इस वजह से कहते हैं) ताकि ख़ुदा (इस ख्याल को) उनके दिलों में (बाइसे) हसरत बना दे और (यूं तो) ख़ुदा ही जिलाता और मारता है और जो कुछ तुम करते हो ख़ुदा उसे देख रहा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,157,'Aal-i-Imraan','وَلَئِن قُتِلۡتُمۡ فِي سَبِيلِ ٱللَّهِ أَوۡ مُتُّمۡ لَمَغۡفِرَةࣱ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَيۡرࣱ مِّمَّا يَجۡمَعُونَ','اور اگر تم خدا کے رستے میں مارے جاؤ یا مرجاؤ تو جو (مال و متاع) لوگ جمع کرتے ہیں اس سے خدا کی بخشش اور رحمت کہیں بہتر ہے','Should you be martyred or die in the cause of Allah, then His forgiveness and mercy are far better than whatever ˹wealth˺ those ˹who stay behind˺ accumulate','और अगर तुम ख़ुदा की राह में मारे जाओ या (अपनी मौत से) मर जाओ तो बेशक ख़ुदा की बख्शिश और रहमत इस (माल व दौलत) से जिसको तुम जमा करते हो ज़रूर बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,158,'Aal-i-Imraan','وَلَئِن مُّتُّمۡ أَوۡ قُتِلۡتُمۡ لَإِلَى ٱللَّهِ تُحۡشَرُونَ','اور اگر تم مرجاؤ یا مارے جاؤ خدا کے حضور میں ضرور اکھٹے کئے جاؤ گے','Whether you die or are martyred—all of you will be gathered before Allah','और अगर तुम (अपनी मौत से) मरो या मारे जाओ (आख़िरकार) ख़ुदा ही की तरफ़ (क़ब्रों से) उठाए जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,159,'Aal-i-Imraan','فَبِمَا رَحۡمَةࣲ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ','(اے محمدﷺ) خدا کی مہربانی سے تمہاری افتاد مزاج ان لوگوں کے لئے نرم واقع ہوئی ہے۔ اور اگر تم بدخو اور سخت دل ہوتے تو یہ تمہارے پاس سے بھاگ کھڑے ہوتے۔ تو ان کو معاف کردو اور ان کے لئے (خدا سے) مغفرت مانگو۔ اور اپنے کاموں میں ان سے مشورت لیا کرو۔ اور جب (کسی کام کا) عزم مصمم کرلو تو خدا پر بھروسا رکھو۔ بےشک خدا بھروسا رکھنے والوں کو دوست رکھتا ہے','It is out of Allah’s mercy that you ˹O Prophet˺ have been lenient with them. Had you been cruel or hard-hearted, they would have certainly abandoned you. So pardon them, ask Allah’s forgiveness for them, and consult with them in ˹conducting˺ matters. Once you make a decision, put your trust in Allah. Surely Allah loves those who trust in Him','(तो ऐ रसूल ये भी) ख़ुदा की एक मेहरबानी है कि तुम (सा) नरमदिल (सरदार) उनको मिला और तुम अगर बदमिज़ाज और सख्त दिल होते तब तो ये लोग (ख़ुदा जाने कब के) तुम्हारे गिर्द से तितर बितर हो गए होते पस (अब भी) तुम उनसे दरगुज़र करो और उनके लिए मग़फेरत की दुआ मॉगो और (साबिक़ दस्तूरे ज़ाहिरा) उनसे काम काज में मशवरा कर लिया करो (मगर) इस पर भी जब किसी काम को ठान लो तो ख़ुदा ही पर भरोसा रखो (क्योंकि जो लोग ख़ुदा पर भरोसा रखते हैं ख़ुदा उनको ज़रूर दोस्त रखता है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,160,'Aal-i-Imraan','إِن يَنصُرۡكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمۡۖ وَإِن يَخۡذُلۡكُمۡ فَمَن ذَا ٱلَّذِي يَنصُرُكُم مِّنۢ بَعۡدِهِۦۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ','اور خدا تمہارا مددگار ہے تو تم پر کوئی غالب نہیں آسکتا۔ اور اگر وہ تمہیں چھوڑ دے تو پھر کون ہے کہ تمہاری مدد کرے اور مومنوں کو چاہیئے کہ خدا ہی پر بھروسا رکھیں','If Allah helps you, none can defeat you. But if He denies you help, then who else can help you? So in Allah let the believers put their trust','(मुसलमानों याद रखो) अगर ख़ुदा ने तुम्हारी मदद की तो फिर कोई तुमपर ग़ालिब नहीं आ सकता और अगर ख़ुदा तुमको छोड़ दे तो फिर कौन ऐसा है जो उसके बाद तुम्हारी मदद को खड़ा हो और मोमिनीन को चाहिये कि ख़ुदा ही पर भरोसा रखें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,161,'Aal-i-Imraan','وَمَا كَانَ لِنَبِيٍّ أَن يَغُلَّۚ وَمَن يَغۡلُلۡ يَأۡتِ بِمَا غَلَّ يَوۡمَ ٱلۡقِيَٰمَةِۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسࣲ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ','اور کبھی نہیں ہوسکتا کہ پیغمبر (خدا) خیانت کریں۔ اور خیانت کرنے والوں کو قیامت کے دن خیانت کی ہوئی چیز (خدا کے روبرو) لاحاضر کرنی ہوگی۔ پھر ہر شخص کو اس کے اعمال کا پورا پورا بدلا دیا جائے گا اور بےانصافی نہیں کی جائے گی','It is not appropriate for a prophet to illegally withhold spoils of war. And whoever does so, it will be held against them on the Day of Judgment. Then every soul will be paid in full for what it has done, and none will be wronged','और (तुम्हारा गुमान बिल्कुल ग़लत है) किसी नबी की (हरगिज़) ये शान नहीं कि ख्यानत करे और ख्यानत करेगा तो जो चीज़ ख्यानत की है क़यामत के दिन वही चीज़ (बिलकुल वैसा ही) ख़ुदा के सामने लाना होगा फिर हर शख्स अपने किए का पूरा पूरा बदला पाएगा और उनकी किसी तरह हक़तल्फ़ी नहीं की जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,162,'Aal-i-Imraan','أَفَمَنِ ٱتَّبَعَ رِضۡوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطࣲ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ','بھلا جو شخص خدا کی خوشنودی کا تابع ہو وہ اس شخص کی طرح (مرتکب خیانت) ہوسکتا ہے جو خدا کی ناخوشی میں گرفتار ہو اور جس کا ٹھکانہ دوزخ ہے، اور وہ برا ٹھکانا ہے','Are those who seek Allah’s pleasure like those who deserve Allah’s wrath? Hell is their home. What an evil destination','भला जो शख्स ख़ुदा की ख़ुशनूदी का पाबन्द हो क्या वह उस शख्स के बराबर हो सकता है जो ख़ुदा के गज़ब में गिरफ्तार हो और जिसका ठिकाना जहन्नुम है और वह क्या बुरा ठिकाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,163,'Aal-i-Imraan','هُمۡ دَرَجَٰتٌ عِندَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ','ان لوگوں کے خدا کے ہاں (مختلف اور متفاوت) درجے ہیں اور خدا ان کے سب اعمال کو دیکھ رہا ہے','They ˹each˺ have varying degrees in the sight of Allah. And Allah is All-Seeing of what they do','वह लोग खुदा के यहॉ मुख्तलिफ़ दरजों के हैं और जो कुछ वह करते हैं ख़ुदा देख रहा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,164,'Aal-i-Imraan','لَقَدۡ مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ إِذۡ بَعَثَ فِيهِمۡ رَسُولࣰ ا مِّنۡ أَنفُسِهِمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلࣲ مُّبِينٍ','خدا نے مومنوں پر بڑا احسان کیا ہے کہ ان میں انہیں میں سے ایک پیغمبر بھیجے۔ جو ان کو خدا کی آیتیں پڑھ پڑھ کر سناتے اور ان کو پاک کرتے اور (خدا کی) کتاب اور دانائی سکھاتے ہیں اور پہلے تو یہ لوگ صریح گمراہی میں تھے','Indeed, Allah has done the believers a ˹great˺ favour by raising a messenger from among them—reciting to them His revelations, purifying them, and teaching them the Book and wisdom. For indeed they had previously been clearly astray','ख़ुदा ने तो ईमानदारों पर बड़ा एहसान किया कि उनके वास्ते उन्हीं की क़ौम का एक रसूल भेजा जो उन्हें खुदा की आयतें पढ़ पढ़ के सुनाता है और उनकी तबीयत को पाकीज़ा करता है और उन्हें किताबे (ख़ुदा) और अक्ल की बातें सिखाता है अगरचे वह पहले खुली हुई गुमराही में पडे थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,165,'Aal-i-Imraan','أَوَلَمَّآ أَصَٰبَتۡكُم مُّصِيبَةࣱ قَدۡ أَصَبۡتُم مِّثۡلَيۡهَا قُلۡتُمۡ أَنَّىٰ هَٰذَاۖ قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ‏','(بھلا یہ) کیا (بات ہے کہ) جب (اُحد کے دن کافر کے ہاتھ سے) تم پر مصیبت واقع ہوئی حالانکہ (جنگ بدر میں) اس سے دوچند مصیبت تمہارے ہاتھ سے ان پر پڑچکی ہے توتم چلا اٹھے کہ (ہائے) آفت (ہم پر) کہاں سے آپڑی کہہ دو کہ یہ تمہاری ہی شامت اعمال ہے (کہ تم نے پیغمبر کے حکم کے خلاف کیا) بےشک خدا ہر چیز پر قادر ہے','Why is it when you suffered casualties ˹at Uḥud˺—although you had made your enemy suffer twice as much ˹at Badr˺—you protested, “How could this be?”? Say, ˹O Prophet,˺ “It is because of your disobedience.” Surely Allah is Most Capable of everything','मुसलमानों क्या जब तुमपर (जंगे ओहद) में वह मुसीबत पड़ी जिसकी दूनी मुसीबत तुम (कुफ्फ़ार पर) डाल चुके थे तो (घबरा के) कहने लगे ये (आफ़त) कहॉ से आ गयी (ऐ रसूल) तुम कह दो कि ये तो खुद तुम्हारी ही तरफ़ से है (न रसूल की मुख़ालेफ़त करते न सज़ा होती) बेशक ख़ुदा हर चीज़ पर क़ादिर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,166,'Aal-i-Imraan','وَمَآ أَصَٰبَكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ فَبِإِذۡنِ ٱللَّهِ وَلِيَعۡلَمَ ٱلۡمُؤۡمِنِينَ','اور جو مصیبت تم پر دونوں جماعتوں کے مقابلے کے دن واقع ہوئی سو خدا کے حکم سے (واقع ہوئی) اور (اس سے) یہ مقصود تھا کہ خدا مومنوں کو اچھی طرح معلوم','So what you suffered on the day the two armies met was by Allah’s Will, so that He might distinguish the ˹true˺ believers','और जिस दिन दो जमाअतें आपस में गुंथ गयीं उस दिन तुम पर जो मुसीबत पड़ी वह तुम्हारी शरारत की वजह से (ख़ुदा के इजाजत की वजह से आयी) और ताकि ख़ुदा सच्चे ईमान वालों को देख ले');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,167,'Aal-i-Imraan','وَلِيَعۡلَمَ ٱلَّذِينَ نَافَقُواْۚ وَقِيلَ لَهُمۡ تَعَالَوۡاْ قَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ أَوِ ٱدۡفَعُواْۖ قَالُواْ لَوۡ نَعۡلَمُ قِتَالࣰ ا لَّٱتَّبَعۡنَٰكُمۡۗ هُمۡ لِلۡكُفۡرِ يَوۡمَئِذٍ أَقۡرَبُ مِنۡهُمۡ لِلۡإِيمَٰنِۚ يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ وَٱللَّهُ أَعۡلَمُ بِمَا يَكۡتُمُونَ','اور منافقوں کو بھی معلوم کرلے اور (جب) ان سے کہا گیا کہ آؤ خدا کے رستے میں جنگ کرو یا (کافروں کے) حملوں کو روکو۔ تو کہنے لگے کہ اگر ہم کو لڑائی کی خبر ہوتی تو ہم ضرور تمہارے ساتھ رہتے یہ اس دن ایمان کی نسبت کفر سے زیادہ قریب تھے منہ سے وہ باتیں کہتے ہیں جو ان کے دل میں نہیں ہیں۔ اور جو کچھ یہ چھپاتے ہیں خدا ان سے خوب واقف ہے','and expose the hypocrites. When it was said to them, “Come fight in the cause of Allah or ˹at least˺ defend yourselves,” they replied, “If we had known there was fighting, we would have definitely gone with you.” They were closer to disbelief than to belief on that day—for saying with their mouths what was not in their hearts. Allah is All-Knowing of what they hide','और मुनाफ़िक़ों को देख ले (कि कौन है) और मुनाफ़िक़ों से कहा गया कि आओ ख़ुदा की राह में जेहाद करो या (ये न सही अपने दुशमन को) हटा दो तो कहने लगे (हाए क्या कहीं) अगर हम लड़ना जानते तो ज़रूर तुम्हारा साथ देते ये लोग उस दिन बनिस्बते ईमान के कुफ़्र के ज्यादा क़रीब थे अपने मुंह से वह बातें कह देते हैं जो उनके दिल में (ख़ाक) नहीं होतीं और जिसे वह छिपाते हैं ख़ुदा उसे ख़ूब जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,168,'Aal-i-Imraan','ٱلَّذِينَ قَالُواْ لِإِخۡوَٰنِهِمۡ وَقَعَدُواْ لَوۡ أَطَاعُونَا مَا قُتِلُواْۗ قُلۡ فَٱدۡرَءُواْ عَنۡ أَنفُسِكُمُ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ','یہ خود تو (جنگ سے بچ کر) بیٹھ ہی رہے تھے مگر (جنہوں نے راہ خدا میں جانیں قربان کردیں) اپنے (ان) بھائیوں کے بارے میں بھی کہتے ہیں کہ اگر ہمارا کہا مانتے تو قتل نہ ہوتے۔ کہہ دو کہ اگر سچے ہو تو اپنے اوپر سے موت کو ٹال دینا','Those who sat at home, saying about their brothers, “Had they listened to us, they would not have been killed.” Say, ˹O Prophet,˺ “Try not to die if what you say is true!”','(ये वही लोग हैं) जो (आप चैन से घरों में बैठे रहते है और अपने शहीद) भाईयों के बारे में कहने लगे काश हमारी पैरवी करते तो न मारे जाते (ऐ रसूल) उनसे कहो (अच्छा) अगर तुम सच्चे हो तो ज़रा अपनी जान से मौत को टाल दो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,169,'Aal-i-Imraan','وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ','جو لوگ خدا کی راہ میں مارے گئے ان کو مرے ہوئے نہ سمجھنا (وہ مرے ہوئے نہیں ہیں) بلکہ خدا کے نزدیک زندہ ہیں اور ان کو رزق مل رہا ہے','Never think of those martyred in the cause of Allah as dead. In fact, they are alive with their Lord, well provided for—','और जो लोग ख़ुदा की राह में शहीद किए गए उन्हें हरगिज़ मुर्दा न समझना बल्कि वह लोग जीते जागते मौजूद हैं अपने परवरदिगार की तरफ़ से वह (तरह तरह की) रोज़ी पाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,170,'Aal-i-Imraan','فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ وَيَسۡتَبۡشِرُونَ بِٱلَّذِينَ لَمۡ يَلۡحَقُواْ بِهِم مِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','جو کچھ خدا نے ان کو اپنے فضل سے بخش رکھا ہے اس میں خوش ہیں۔ اور جو لوگ ان کے پیچھے رہ گئے اور (شہید ہوکر) ان میں شامل نہیں ہوسکے ان کی نسبت خوشیاں منا رہے ہیں کہ (قیامت کے دن) ان کو بھی نہ کچھ خوف ہوگا اور نہ وہ غمناک ہوں گے','rejoicing in Allah’s bounties and being delighted for those yet to join them. There will be no fear for them, nor will they grieve','और ख़ुदा ने जो फ़ज़ल व करम उन पर किया है उसकी (ख़ुशी) से फूले नहीं समाते और जो लोग उनसे पीछे रह गए और उनमें आकर शामिल नहीं हुए उनकी निस्बत ये (ख्याल करके) ख़ुशियॉ मनाते हैं कि (ये भी शहीद हों तो) उनपर न किसी क़िस्म का ख़ौफ़ होगा और न आज़ुर्दा ख़ातिर होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,171,'Aal-i-Imraan','۞يَسۡتَبۡشِرُونَ بِنِعۡمَةࣲ مِّنَ ٱللَّهِ وَفَضۡلࣲ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُؤۡمِنِينَ','اور خدا کے انعامات اور فضل سے خوش ہورہے ہیں۔ اور اس سے کہ خدا مومنوں کا اجر ضائع نہیں کرتا','They are joyful for receiving Allah’s grace and bounty, and that Allah does not deny the reward of the believers','ख़ुदा नेअमत और उसके फ़ज़ल (व करम) और इस बात की ख़ुशख़बरी पाकर कि ख़ुदा मोमिनीन के सवाब को बरबाद नहीं करता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,172,'Aal-i-Imraan','ٱلَّذِينَ ٱسۡتَجَابُواْ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعۡدِ مَآ أَصَابَهُمُ ٱلۡقَرۡحُۚ لِلَّذِينَ أَحۡسَنُواْ مِنۡهُمۡ وَٱتَّقَوۡاْ أَجۡرٌ عَظِيمٌ','جنہوں نے باوجود زخم کھانے کے خدا اور رسول (کے حکم) کو قبول کیا جو لوگ ان میں نیکوکار اور پرہیزگار ہیں ان کے لئے بڑا ثواب ہے','˹As for˺ those who responded to the call of Allah and His Messenger after their injury, those of them who did good and were mindful ˹of Allah˺ will have a great reward','निहाल हो रहे हैं (जंगे ओहद में) जिन लोगों ने जख्म खाने के बाद भी ख़ुदा और रसूल का कहना माना उनमें से जिन लोगों ने नेकी और परहेज़गारी की (सब के लिये नहीं सिर्फ) उनके लिये बड़ा सवाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,173,'Aal-i-Imraan','ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنࣰ ا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ','(جب) ان سے لوگوں نے آکر بیان کیا کہ کفار نے تمہارے (مقابلے کے) لئے لشکر کثیر) جمع کیا ہے تو ان سے ڈرو۔ تو ان کا ایمان اور زیادہ ہوگیا۔ اور کہنے لگے ہم کو خدا کافی ہے اور وہ بہت اچھا کارساز ہے','Those who were warned, “Your enemies have mobilized their forces against you, so fear them,” the warning only made them grow stronger in faith and they replied, “Allah ˹alone˺ is sufficient ˹as an aid˺ for us and ˹He˺ is the best Protector.”','यह वह हैं कि जब उनसे लोगों ने आकर कहना शुरू किया कि (दुशमन) लोगों ने तुम्हारे (मुक़ाबले के) वास्ते (बड़ा लश्कर) जमा किया है पस उनसे डरते (तो बजाए ख़ौफ़ के) उनका ईमान और ज्यादा हो गया और कहने लगे (होगा भी) ख़ुदा हमारे वास्ते काफ़ी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,174,'Aal-i-Imraan','فَٱنقَلَبُواْ بِنِعۡمَةࣲ مِّنَ ٱللَّهِ وَفَضۡلࣲ لَّمۡ يَمۡسَسۡهُمۡ سُوٓءࣱ وَٱتَّبَعُواْ رِضۡوَٰنَ ٱللَّهِۗ وَٱللَّهُ ذُو فَضۡلٍ عَظِيمٍ','پھر وہ خدا کی نعمتوں اور اس کے فضل کے ساتھ (خوش وخرم) واپس آئے ان کو کسی طرح کا ضرر نہ پہنچا۔ اور وہ خدا کی خوشنودی کے تابع رہے۔ اور خدا بڑے فضل کا مالک ہے','So they returned with Allah’s favours and grace, suffering no harm. For they sought to please Allah. And surely Allah is ˹the˺ Lord of infinite bounty','और वह क्या अच्छा कारसाज़ है फिर (या तो हिम्मत करके गए मगर जब लड़ाई न हुई तो) ये लोग ख़ुदा की नेअमत और फ़ज़ल के साथ (अपने घर) वापस आए और उन्हें कोई बुराई छू भी नहीं गयी और ख़ुदा की ख़ुशनूदी के पाबन्द रहे और ख़ुदा बड़ा फ़ज़ल करने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,175,'Aal-i-Imraan','إِنَّمَا ذَٰلِكُمُ ٱلشَّيۡطَٰنُ يُخَوِّفُ أَوۡلِيَآءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِينَ','یہ (خوف دلانے والا) تو شیطان ہے جو اپنے دوستوں سے ڈراتا ہے تو اگر تم مومن ہو تو ان سے مت ڈرنا اور مجھ ہی سے ڈرتے رہنا','That ˹warning˺ was only ˹from˺ Satan, trying to prompt you to fear his followers. So do not fear them; fear Me if you are ˹true˺ believers','यह (मुख्बिर) बस शैतान था जो सिर्फ़ अपने दोस्तों को (रसूल का साथ देने से) डराता है पस तुम उनसे तो डरो नहीं अगर सच्चे मोमिन हो तो मुझ ही से डरते रहो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,176,'Aal-i-Imraan','وَلَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِۚ إِنَّهُمۡ لَن يَضُرُّواْ ٱللَّهَ شَيۡـࣰٔ اۚ يُرِيدُ ٱللَّهُ أَلَّا يَجۡعَلَ لَهُمۡ حَظࣰّ ا فِي ٱلۡأٓخِرَةِۖ وَلَهُمۡ عَذَابٌ عَظِيمٌ','اور جو لوگ کفر میں جلدی کرتے ہیں ان (کی وجہ) سے غمگین نہ ہونا۔ یہ خدا کا کچھ نقصان نہیں کرسکتے خدا چاہتا ہے کہ آخرت میں ان کو کچھ حصہ نہ دے اور ان کے لئے بڑا عذاب تیار ہے','˹O Prophet!˺ Do not grieve for those who race to disbelieve—surely they will not harm Allah in the least. It is Allah’s Will to disallow them a share in the Hereafter, and they will suffer a tremendous punishment','और (ऐ रसूल) जो लोग कुफ़्र की (मदद) में पेश क़दमी कर जाते हैं उनकी वजह से तुम रन्ज न करो क्योंकि ये लोग ख़ुदा को कुछ ज़रर नहीं पहुँचा सकते (बल्कि) ख़ुदा तो ये चाहता है कि आख़ेरत में उनका हिस्सा न क़रार दे और उनके लिए बड़ा (सख्त) अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,177,'Aal-i-Imraan','إِنَّ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ لَن يَضُرُّواْ ٱللَّهَ شَيۡـࣰٔ اۖ وَلَهُمۡ عَذَابٌ أَلِيمࣱ‏','جن لوگوں نے ایمان کے بدلے کفر خریدا وہ خدا کا کچھ نہیں بگاڑ سکتے اور ان کو دکھ دینے والا عذاب ہوگا','Those who trade belief for disbelief will never harm Allah in the least, and they will suffer a painful punishment','बेशक जिन लोगों ने ईमान के एवज़ कुफ़्र ख़रीद किया वह हरगिज़ खुदा का कुछ भी नहीं बिगाड़ेंगे (बल्कि आप अपना) और उनके लिए दर्दनाक अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,178,'Aal-i-Imraan','وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُوٓاْ أَنَّمَا نُمۡلِي لَهُمۡ خَيۡرࣱ لِّأَنفُسِهِمۡۚ إِنَّمَا نُمۡلِي لَهُمۡ لِيَزۡدَادُوٓاْ إِثۡمࣰ اۖ وَلَهُمۡ عَذَابࣱ مُّهِينࣱ‏','اور کافر لوگ یہ نہ خیال کریں کہ ہم جو ان کو مہلت دیئے جاتے ہیں تو یہ ان کے حق میں اچھا ہے۔ (نہیں بلکہ) ہم ان کو اس لئے مہلت دیتے ہیں کہ اور گناہ کرلیں۔ آخرکار ان کو ذلیل کرنے والا عذاب ہوگا','Those who disbelieve should not think that living longer is good for them. They are only given more time to increase in sin, and they will suffer a humiliating punishment','और जिन लोगों ने कुफ़्र इख्तियार किया वह हरगिज़ ये न ख्याल करें कि हमने जो उनको मोहलत व बेफिक्री दे रखी है वह उनके हक़ में बेहतर है (हालॉकि) हमने मोहल्लत व बेफिक्री सिर्फ इस वजह से दी है ताकि वह और ख़ूब गुनाह कर लें और (आख़िर तो) उनके लिए रूसवा करने वाला अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,179,'Aal-i-Imraan','مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلۡمُؤۡمِنِينَ عَلَىٰ مَآ أَنتُمۡ عَلَيۡهِ حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ عَلَى ٱلۡغَيۡبِ وَلَٰكِنَّ ٱللَّهَ يَجۡتَبِي مِن رُّسُلِهِۦ مَن يَشَآءُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ فَلَكُمۡ أَجۡرٌ عَظِيمࣱ‏','(لوگو) جب تک خدا ناپاک کو پاک سے الگ نہ کردے گا مومنوں کو اس حال میں جس میں تم ہو ہرگز نہیں رہنے دے گا۔ اور الله تم کوغیب کی باتوں سے بھی مطلع نہیں کرے گاالبتہ خدا اپنے پیغمبروں میں سے جسے چاہتا ہے انتخاب کرلیتا ہے۔ تو تم خدا پر اور اس کے رسولوں پر ایمان لاؤاور اگر ایمان لاؤ گے اور پرہیزگاری کرو گے تو تم کو اجر عظیم ملے گا','Allah would not leave the believers in the condition you were in, until He distinguished the good from the evil ˹among you˺. Nor would Allah ˹directly˺ reveal to you the unseen, but He chooses whoever He wills as a messenger. So believe in Allah and His messengers. And if you are faithful and mindful ˹of Allah˺, you will receive a great reward','(मुनाफ़िक़ो) ख़ुदा ऐसा नहीं कि बुरे भले की तमीज़ किए बगैर जिस हालत पर तुम हो उसी हालत पर मोमिनों को भी छोड़ दे और ख़ुदा ऐसा भी नहीं है कि तुम्हें गैब की बातें बता दे मगर (हॉ) ख़ुदा अपने रसूलों में जिसे चाहता है (गैब बताने के वास्ते) चुन लेता है पस ख़ुदा और उसके रसूलों पर ईमान लाओ और अगर तुम ईमान लाओगे और परहेज़गारी करोगे तो तुम्हारे वास्ते बड़ी जज़ाए ख़ैर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,180,'Aal-i-Imraan','وَلَا يَحۡسَبَنَّ ٱلَّذِينَ يَبۡخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَيۡرࣰ ا لَّهُمۖ بَلۡ هُوَ شَرࣱّ لَّهُمۡۖ سَيُطَوَّقُونَ مَا بَخِلُواْ بِهِۦ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ‏','جو لوگ مال میں جو خدا نے اپنے فضل سے ان کو عطا فرمایا ہے بخل کرتے ہیں وہ اس بخل کو اپنے حق میں اچھا نہ سمجھیں۔ (وہ اچھا نہیں) بلکہ ان کے لئے برا ہے وہ جس مال میں بخل کرتے ہیں قیامت کے دن اس کا طوق بنا کر ان کی گردنوں میں ڈالا جائے گا۔ اور آسمانوں اور زمین کا وارث خدا ہی ہے۔ اور جو عمل تم کرتے ہوخدا کو معلوم ہے','And do not let those who ˹greedily˺ withhold Allah’s bounties think it is good for them—in fact, it is bad for them! They will be leashed ˹by their necks˺ on the Day of Judgment with whatever ˹wealth˺ they used to withhold. And Allah is the ˹sole˺ inheritor of the heavens and the earth. And Allah is All-Aware of what you do','और जिन लोगों को ख़ुदा ने अपने फ़ज़ल (व करम) से कुछ दिया है (और फिर) बुख्ल करते हैं वह हरगिज़ इस ख्याल में न रहें कि ये उनके लिए (कुछ) बेहतर होगा बल्कि ये उनके हक़ में बदतर है क्योंकि जिस (माल) का बुख्ल करते हैं अनक़रीब ही क़यामत के दिन उसका तौक़ बनाकर उनके गले में पहनाया जाएगा और सारे आसमान व ज़मीन की मीरास ख़ुदा ही की है और जो कुछ तुम करते हो ख़ुदा उससे ख़बरदार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,181,'Aal-i-Imraan','لَّقَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ فَقِيرࣱ وَنَحۡنُ أَغۡنِيَآءُۘ سَنَكۡتُبُ مَا قَالُواْ وَقَتۡلَهُمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقࣲّ وَنَقُولُ ذُوقُواْ عَذَابَ ٱلۡحَرِيقِ','خدا نے ان لوگوں کا قول سن لیا ہے جو کہتے ہیں کہ خدا فقیر ہے۔ اور ہم امیر ہیں۔ یہ جو کہتے ہیں ہم اس کو لکھ لیں گے۔ اور پیغمبروں کو جو یہ ناحق قتل کرتے رہے ہیں اس کو بھی (قلمبند کر رکھیں گے) اور (قیامت کے روز) کہیں گے کہ عذاب (آتش) سوزاں کے مزے چکھتے رہو','Indeed, Allah has heard those ˹among the Jews˺ who said, “Allah is poor; we are rich!” We have certainly recorded their slurs and their killing of prophets unjustly. Then We will say, “Taste the torment of burning','जो लोग (यहूद) ये कहते हैं कि ख़ुदा तो कंगाल है और हम बड़े मालदार हैं ख़ुदा ने उनकी ये बकवास सुनी उन लोगों ने जो कुछ किया उसको और उनका पैग़म्बरों को नाहक़ क़त्ल करना हम अभी से लिख लेते हैं और (आज तो जो जी में कहें मगर क़यामत के दिन) हम कहेंगे कि अच्छा तो लो (अपनी शरारत के एवज़ में) जलाने वाले अज़ाब का मज़ा चखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,182,'Aal-i-Imraan','ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّامࣲ لِّلۡعَبِيدِ','یہ ان کاموں کی سزا ہے جو تمہارے ہاتھ آگے بھیجتے رہے ہیں اور خدا تو بندوں پر مطلق ظلم نہیں کرتا','This is ˹the reward˺ for what your hands have done. And Allah is never unjust to ˹His˺ creation.”','ये उन्हीं कामों का बदला है जिनको तुम्हारे हाथों ने (ज़ादे आख़ेरत बना कर) पहले से भेजा है वरना ख़ुदा तो कभी अपने बन्दों पर ज़ुल्म करने वाला नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,183,'Aal-i-Imraan','ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ عَهِدَ إِلَيۡنَآ أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ يَأۡتِيَنَا بِقُرۡبَانࣲ تَأۡكُلُهُ ٱلنَّارُۗ قُلۡ قَدۡ جَآءَكُمۡ رُسُلࣱ مِّن قَبۡلِي بِٱلۡبَيِّنَٰتِ وَبِٱلَّذِي قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوهُمۡ إِن كُنتُمۡ صَٰدِقِينَ','جو لوگ کہتے ہی کہ خدا نے ہمیں حکم بھیجا ہے کہ جب تک کوئی پیغمبر ہمارے پاس ایسی نیاز لے کر نہ آئے جس کو آگ آکر کھا جائے تب تک ہم اس پر ایمان نہ لائیں گے (اے پیغمبر ان سے) کہہ دو کہ مجھ سے پہلے کئی پیغمبر تمہارے پاس کھلی ہوئی نشانیاں لے کر آئے اور وہ (معجزہ) بھی لائے جو تم کہتے ہو تو اگر سچے ہو تو تم نے ان کو قتل کیوں کیا؟','Those ˹are the same people˺ who say, “Allah has commanded us not to believe in any messenger unless he brings us an offering to be consumed by fire ˹from the sky˺.” Say, ˹O Prophet,˺ “Other prophets did in fact come to you before me with clear proofs and ˹even˺ what you demanded—why then did you kill them, if what you say is true?”','(यह वही लोग हैं) जो कहते हैं कि ख़ुदा ने तो हमसे वायदा किया है कि जब तक कोई रसूल हमें ये (मौजिज़ा) न दिखा दे कि वह कुरबानी करे और उसको (आसमानी) आग आकर चट कर जाए उस वक्त तक हम ईमान न लाएंगें (ऐ रसूल) तुम कह दो कि (भला) ये तो बताओ बहुतेरे पैग़म्बर मुझसे क़ब्ल तुम्हारे पास वाजे व रौशन मौजिज़ात और जिस चीज़ की तुमने (उस वक्त) फ़रमाइश की है (वह भी) लेकर आए फिर तुम अगर (अपने दावे में) सच्चे तो तुमने क्यों क़त्ल किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,184,'Aal-i-Imraan','فَإِن كَذَّبُوكَ فَقَدۡ كُذِّبَ رُسُلࣱ مِّن قَبۡلِكَ جَآءُو بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلۡكِتَٰبِ ٱلۡمُنِيرِ','پھر اگر یہ لوگ تم کو سچا نہ سمجھیں تو تم سے پہلے بہت سے پیغمبر کھلی ہوئی نشانیاں اور صحیفے اور روشن کتابیں لے کر آچکے ہیں اور لوگوں نے ان کو بھی سچا نہیں سمجھا','If you are rejected by them, so too were messengers before you who came with clear proofs, divine Books, and enlightening Scriptures','(ऐ रसूल) अगर वह इस पर भी तुम्हें झुठलाएं तो (तुम आज़ुर्दा न हो क्योंकि) तुमसे पहले भी बहुत से पैग़म्बर रौशन मौजिज़े और सहीफे और नूरानी किताब लेकर आ चुके हैं (मगर) फिर भी लोगों ने आख़िर झुठला ही छोड़ा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,185,'Aal-i-Imraan','كُلُّ نَفۡسࣲ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۖ فَمَن زُحۡزِحَ عَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ','ہر متنفس کو موت کا مزا چکھنا ہے اور تم کو قیامت کے دن تمہارے اعمال کا پورا پورا بدلا دیا جائے گا۔ تو جو شخص آتش جہنم سے دور رکھا گیا اور بہشت میں داخل کیا گیا وہ مراد کو پہنچ گیا اور دنیا کی زندگی تو دھوکے کا سامان ہے','Every soul will taste death. And you will only receive your full reward on the Day of Judgment. Whoever is spared from the Fire and is admitted into Paradise will ˹indeed˺ triumph, whereas the life of this world is no more than the delusion of enjoyment','हर जान एक न एक (दिन) मौत का मज़ा चखेगी और तुम लोग क़यामत के दिन (अपने किए का) पूरा पूरा बदला भर पाओगे पस जो शख्स जहन्नुम से हटा दिया गया और बहिश्त में पहुंचा दिया गया पस वही कामयाब हुआ और दुनिया की (चन्द रोज़ा) ज़िन्दगी धोखे की टट्टी के सिवा कुछ नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (3,186,'Aal-i-Imraan','۞لَتُبۡلَوُنَّ فِيٓ أَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذࣰ ى كَثِيرࣰ اۚ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ','(اے اہل ایمان) تمہارے مال و جان میں تمہاری آزمائش کی جائے گی۔ اور تم اہل کتاب سے اور ان لوگوں سے جو مشرک ہیں بہت سی ایذا کی باتیں سنو گے۔ اور تو اگر صبر اور پرہیزگاری کرتے رہو گے تو یہ بڑی ہمت کے کام ہیں','You ˹believers˺ will surely be tested in your wealth and yourselves, and you will certainly hear many hurtful words from those who were given the Scripture before you and ˹from˺ the polytheists. But if you are patient and mindful ˹of Allah˺—surely this is a resolve to aspire to','(मुसलमानों) तुम्हारे मालों और जानों का तुमसे ज़रूर इम्तेहान लिया जाएगा और जिन लोगो को तुम से पहले किताबे ख़ुदा दी जा चुकी है (यहूद व नसारा) उनसे और मुशरेकीन से बहुत ही दुख दर्द की बातें तुम्हें ज़रूर सुननी पड़ेंगी और अगर तुम (उन मुसीबतों को) झेल जाओगे और परहेज़गारी करते रहोगे तो बेशक ये बड़ी हिम्मत का काम है');
